    }

    function withdrawSavaxFromAvaxSavaxInOtherTokenYY(
        uint256 amount,
        uint256 minOut
    ) external returns (uint256 amountOut) {
        return
            _withdrawToken(
                "AVAX",
                "sAVAX",
                WOMBAT_sAVAX_AVAX_LP_AVAX,
                YY_sAVAX_AVAX_LP_AVAX,
