            _withdrawToken(
                "AVAX",
                "ggAVAX",
                WOMBAT_ggAVAX_AVAX_LP_AVAX,
                YY_ggAVAX_AVAX_LP_AVAX,
                WOMBAT_ggAVAX_AVAX_POOL,
