        if (!tokenManager.isGmxMarketWhitelisted(gmToken)) revert MarketNotWhitelisted();

        gmAmount = IERC20(gmToken).balanceOf(address(this)) < gmAmount
            ? IERC20(gmToken).balanceOf(address(this))
            : gmAmount;

