import "../interfaces/facets/IPrimeLeverageFacet.sol";
import "../interfaces/ITokenManager.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@uniswap/lib/contracts/libraries/TransferHelper.sol";
import "../ReentrancyGuardKeccak.sol";
import "../lib/DiamondMethodsAccess.sol";
import "../PrimeAccountModifiers.sol";

//this path is updated during deployment
import "../lib/arbitrum/DeploymentConstants.sol";

contract PrimeLeverageFacet is  IPrimeLeverageFacet,ReentrancyGuardKeccak, DiamondMethodsAccess, PrimeAccountModifiers {

    using TransferHelper for address;

    // for token burning
    address private constant BURN_ADDRESS = 0x000000000000000000000000000000000000dEaD;


    ///@dev clone of IAssetsOperationsFacet.Fund event
    event Funded(address indexed user, bytes32 indexed asset, uint256 amount, uint256 timestamp);


    /**
    * @notice A modified version of fund() method in AssetsOperationsFacet as a workaround for PRIME price feeds.
    * Funds the loan with a specified amount of a defined token
    * @dev Requires approval for ERC20 token on frontend side
    * @param _amount to be funded
    **/
    function depositPrime( uint256 _amount) public virtual onlyOwner noBorrowInTheSameBlock  nonReentrant remainsSolvent {

        require(_amount > 0, "Amount must be > 0 to deposit PRIME");
        IERC20Metadata token = getERC20TokenInstance(bytes32("PRIME"), true);
        _amount = Math.min(_amount, token.balanceOf(msg.sender));

        address(token).safeTransferFrom(msg.sender, address(this), _amount);

        ITokenManager tokenManager = DeploymentConstants.getTokenManager();
        syncExposureOfPrime(tokenManager, address(token));

        emit Funded(msg.sender, bytes32("PRIME"), _amount, block.timestamp);
    }


    function activatePremium() private  {
        require(DiamondStorageLib.getPrimeLeverageTier() != LeverageTierLib.LeverageTier.PREMIUM, "Already in premium tier");
        // Update storage
        DiamondStorageLib.setPrimeLeverageTier(LeverageTierLib.LeverageTier.PREMIUM);

        LeverageTierLib.updatePrimeDebtSnapshot(_getDebt());

        emit LeverageTierChanged(msg.sender, LeverageTierLib.LeverageTier.BASIC, LeverageTierLib.LeverageTier.PREMIUM, block.timestamp);
    }   

    /**
     * @dev Activates PREMIUM tier (10x leverage mode) for the user
     */
    function stakePrimeAndActivatePremium() external onlyOwner nonReentrant {
        uint256 totalCollateral = _getTotalValue() - _getDebt();
        uint256 requiredMaxStake = getRequiredPrimeStake(LeverageTierLib.LeverageTier.PREMIUM, totalCollateral * 10); // 10x max debt
        stakePrime(requiredMaxStake);
        DiamondStorageLib.setLastPrimeDebtUpdate(block.timestamp);
        activatePremium();
    }

    /**
     * @dev Deactivates PREMIUM tier back to BASIC tier
     * @param withdrawStake Whether to withdraw excess staked PRIME
     */
    function deactivatePremiumTier(bool withdrawStake) external onlyOwner nonReentrant {
        require(DiamondStorageLib.getPrimeLeverageTier() != LeverageTierLib.LeverageTier.BASIC, "Already in BASIC tier");

        /// @dev gets the current debt, tries to repay it fully before deactivating
        /// if full repayment is not possible, it will revert
        uint256 totalDebt = _getDebt();
        uint256 currentDebt = LeverageTierLib.getCurrentPrimeDebt(totalDebt);
        repayPrimeDebt(currentDebt); // Repay all PRIME debt before downgrading




        LeverageTierLib.LeverageTier oldTier = DiamondStorageLib.getPrimeLeverageTier();
        DiamondStorageLib.setPrimeLeverageTier(LeverageTierLib.LeverageTier.BASIC);

        // Withdraw excess staked PRIME if requested
        if (withdrawStake) {
            ITokenManager tokenManager = DeploymentConstants.getTokenManager();
            address primeTokenAddress = tokenManager.getAssetAddress("PRIME", true);
            uint256 currentStaked = DiamondStorageLib.getStakedTokenAmount(primeTokenAddress);
            uint256 newRequiredStake = getRequiredPrimeStake(LeverageTierLib.LeverageTier.BASIC, _getDebt());

            if (currentStaked > newRequiredStake) {
                uint256 excessStake = currentStaked - newRequiredStake;
                DiamondStorageLib.removeStakedTokenAmount(primeTokenAddress, excessStake);


                emit PrimeUnstaked(msg.sender, excessStake, newRequiredStake, block.timestamp);
            }
        }

        emit LeverageTierChanged(msg.sender, oldTier, LeverageTierLib.LeverageTier.BASIC, block.timestamp);
    }

    /**
     * @dev Stakes additional PRIME tokens (without changing tier)
     * @param amount Amount of PRIME to stake
     */
    function stakePrime(uint256 amount) private {
        require(amount > 0, "Amount must be > 0");
        ITokenManager tokenManager = DeploymentConstants.getTokenManager();
        address primeTokenAddress = tokenManager.getAssetAddress("PRIME", true);

        require(_getAvailableBalance("PRIME") >= amount, "Insufficient PRIME balance");

        uint256 currentStaked = DiamondStorageLib.getStakedTokenAmount(primeTokenAddress);

        DiamondStorageLib.addStakedTokenAmount(primeTokenAddress,amount);

        emit PrimeStaked(msg.sender, amount, currentStaked + amount, block.timestamp);
    }

    function getPrimeStakedAmount() external view returns (uint256) {
        ITokenManager tokenManager = DeploymentConstants.getTokenManager();
        address primeTokenAddress = tokenManager.getAssetAddress("PRIME", true);
        // Return the staked amount of PRIME tokens
        return DiamondStorageLib.getStakedTokenAmount(primeTokenAddress);

    }

    /**
     * @dev Unstakes PRIME tokens (if requirements are still met)
     * @param amount Amount of PRIME to unstake
     */
    function unstakePrime(uint256 amount) external onlyOwner nonReentrant {
        require(amount > 0, "Amount must be > 0");
        ITokenManager tokenManager = DeploymentConstants.getTokenManager();
        address primeTokenAddress = tokenManager.getAssetAddress("PRIME", true);

        uint256 currentStaked = DiamondStorageLib.getStakedTokenAmount(primeTokenAddress);
        require(amount <= currentStaked, "Insufficient staked amount");

        uint256 borrowedValue = _getDebt();
        uint256 remainingStake = currentStaked - amount;

        if (getLeverageTier() != LeverageTierLib.LeverageTier.BASIC) {
            uint256 primeStakingRatio = tokenManager.tieredPrimeStakingRatio(LeverageTierLib.LeverageTier.PREMIUM);
            uint256 requiredPrimeStakeAmount = borrowedValue * primeStakingRatio / (100 * 10 ** 18);
            require(remainingStake >= requiredPrimeStakeAmount, "Would fall below minimum stake requirement for PREMIUM tier");
        }

        // A PREMIUM account with accrued PRIME debt must keep enough staked PRIME to cover
        // that debt, otherwise an unstake could leave the protocol with a PRIME-debt that
        // exceeds available stake even though the USD-denominated stake ratio is satisfied.
        // Settle accrued-but-unsnapshotted debt into recordedPrimeDebt first; reading
        // DiamondStorageLib.getPrimeDebt() directly would let a user time their unstake to
        // bypass the check while accrual sits outside the recorded value.
        LeverageTierLib.updatePrimeDebtSnapshot(borrowedValue);
        uint256 currentPrimeDebt = LeverageTierLib.getCurrentPrimeDebt(borrowedValue);
        require(remainingStake >= currentPrimeDebt, "Would fall below accrued PRIME debt");


        DiamondStorageLib.removeStakedTokenAmount(primeTokenAddress, amount);

        emit PrimeUnstaked(msg.sender, amount, remainingStake, block.timestamp);
    }

    /**
     * @dev Updates the recorded Prime debt with accrued amount
     */
    function updatePrimeDebt() public {
        uint256 totalDebt = _getDebt();
        LeverageTierLib.updatePrimeDebtSnapshot(totalDebt);        
    }

     /**
    * @notice A modified version of _syncExposure() method in DiamondMethodsAccess which doesn't 
    * add PRIME as an owned asset for solvency calculations.
    * @param tokenManager tokenManager instance
    * @param _token to be funded
    **/
    function syncExposureOfPrime(ITokenManager tokenManager, address _token) internal virtual {
        // Tell TokenManager to update the exposure based on current on-chain balance.
        tokenManager.updateUserExposure(address(this), _token);
    }


    /**
     * @dev Repays Prime debt using PRIME tokens
     * @param amount Amount of PRIME to use for debt repayment
     */
    function repayPrimeDebt(uint256 amount) public onlyOwner {
        require(amount > 0, "Amount must be > 0");
        uint256 totalDebt = _getDebt();
        LeverageTierLib.updatePrimeDebtSnapshot(totalDebt);
        uint256 currentDebt = LeverageTierLib.getCurrentPrimeDebt(totalDebt);
        require(currentDebt > 0, "No debt to repay");
        require(_getAvailableBalance("PRIME") >= amount, "Not enough PRIME to repay the debt");
        ITokenManager tokenManager = DeploymentConstants.getTokenManager();
        address primeTokenAddress = tokenManager.getAssetAddress("PRIME", true);
        // to ensure no overpayment of debt, cap the amount to current debt if user tries to repay more than owed
        amount = Math.min(amount, currentDebt);


        // Split: 50% burn, 50% to treasury
        uint256 burnAmount = amount / 2;
        uint256 treasuryAmount = amount - burnAmount;


        primeTokenAddress.safeTransfer(BURN_ADDRESS, burnAmount);


        address treasuryAddress = DeploymentConstants.getTreasuryAddress();
        primeTokenAddress.safeTransfer(treasuryAddress, treasuryAmount);

        // Update debt (need to update the recorded debt, not just subtract from current)
        uint256 recordedDebt = DiamondStorageLib.getPrimeDebt();
        DiamondStorageLib.setPrimeDebt(recordedDebt > amount ? recordedDebt - amount : 0);

        uint256 currentDebtAfter = LeverageTierLib.getCurrentPrimeDebt(totalDebt);

        emit PrimeDebtRepaid(msg.sender, amount, currentDebtAfter, block.timestamp);
    }



    /**
     * @notice Returns required Prime stake for a specific tier and borrowed amount
     */
    function getRequiredPrimeStake(LeverageTierLib.LeverageTier tier, uint256 borrowedValue) public view returns (uint256) {
        ITokenManager tokenManager = DeploymentConstants.getTokenManager();
        uint256 tierStakingRatio = tokenManager.tieredPrimeStakingRatio(tier);
        return (borrowedValue * tierStakingRatio) / (100 * 10 ** 18); // tierStakingRatio is per $100 borrowed
    }




    /**
     * @notice Returns current leverage tier
     */
    function getLeverageTier() public view returns (LeverageTierLib.LeverageTier) {
        return DiamondStorageLib.getPrimeLeverageTier();
    }

    /**
     * @notice Returns leverage tier information for UI display
     */
    function getLeverageTierFullInfo() public view returns (
        LeverageTierLib.LeverageTier currentTier,
        uint256 stakedPrime,
        uint256 recordedDebt
    ) {
        currentTier = DiamondStorageLib.getPrimeLeverageTier();
        stakedPrime = DiamondStorageLib.getStakedTokenAmount(DeploymentConstants.getTokenManager().getAssetAddress("PRIME", true));
        recordedDebt = DiamondStorageLib.getPrimeDebt();
    }

    /**
     * @notice Checks if Prime liquidation should trigger
     */
    function shouldLiquidatePrimeDebt() public returns (bool) {
        LeverageTierLib.LeverageTier currentTier = DiamondStorageLib.getPrimeLeverageTier();
        uint256 totalBorrowedValue = _getDebt();

        LeverageTierLib.updatePrimeDebtSnapshot(totalBorrowedValue);

        ITokenManager tokenManager = DeploymentConstants.getTokenManager();
        uint256 stakedPrime = DiamondStorageLib.getStakedTokenAmount(tokenManager.getAssetAddress("PRIME", true));


        // Get current total borrowed value (in USD)

        // Get the Prime Debt ratio (e.g., 2 PRIME per 100 USD borrowed per year)
        uint256 primeDebtRatio = tokenManager.tieredPrimeDebtRatio(currentTier);

        // Calculate weekly accrual at current borrow level
        /// @dev primeDebtRatio is in 18-decimal precision, must divide by 10**18 to normalize (matches LeverageTierLib.sol:L55)
        uint256 weeklyAccrualAtCurrentBorrow = (totalBorrowedValue * primeDebtRatio * 7 days) / (100 * 365 days * 10 ** 18);

        uint256 primeDebt = DiamondStorageLib.getPrimeDebt();


        ///@dev rather than simply checking primeDebt > stakedPrime, the user gets a buffer of further accrual of another week
        ///@dev so could try and borrow more which would inherently trigger further staking from the PRIME balance
        /// @dev equivalent to (primeDebt - weeklyAccrualAtCurrentBorrow > stakedPrime), but done this way to avoid underflow issues.
        if (primeDebt > weeklyAccrualAtCurrentBorrow + stakedPrime) {
            return true;
        }

        return false;

    }

    /**
     * @dev Emergency liquidation of Prime debt (only callable by whitelisted liquidators)
     */
    function liquidatePrimeDebt() external onlyWhitelistedLiquidators nonReentrant {
        require(shouldLiquidatePrimeDebt(), "Prime liquidation not triggered");


        ///@dev there shouldn't be any accrued debt at this point, since the require check should have triggered 
        ///@dev _updatePrimeDebtSnapshot();
        uint256 primeDebt = DiamondStorageLib.getPrimeDebt(); 
        ITokenManager tokenManager = DeploymentConstants.getTokenManager();
        address primeTokenAddress = tokenManager.getAssetAddress("PRIME", true);
        uint256 stakedPrime = DiamondStorageLib.getStakedTokenAmount(primeTokenAddress);

        // Liquidate staked Prime to cover debt
        uint256 liquidatedAmount = primeDebt < stakedPrime ? primeDebt : stakedPrime;

        // Reduce Prime debt and stake
        uint256 newDebt = primeDebt > liquidatedAmount ? primeDebt - liquidatedAmount : 0;

        DiamondStorageLib.setPrimeDebt(newDebt);

        DiamondStorageLib.removeStakedTokenAmount(primeTokenAddress, liquidatedAmount);

        // Transfer liquidated PRIME: 50% burn, 50% to treasury
        uint256 burnAmount = liquidatedAmount / 2;
        uint256 treasuryAmount = liquidatedAmount - burnAmount;
        primeTokenAddress.safeTransfer(BURN_ADDRESS, burnAmount);
        address treasuryAddress = DeploymentConstants.getTreasuryAddress();
        primeTokenAddress.safeTransfer(treasuryAddress, treasuryAmount);

        // If remaining Prime can't cover remaining debt, force switch to BASIC
        uint256 remainingPrime = stakedPrime - liquidatedAmount;
        uint256 remainingDebt = LeverageTierLib.getCurrentPrimeDebt(_getDebt());
        if (remainingDebt > remainingPrime) {
            LeverageTierLib.LeverageTier oldTier = DiamondStorageLib.getPrimeLeverageTier();
            DiamondStorageLib.setPrimeLeverageTier(LeverageTierLib.LeverageTier.BASIC);
            emit LeverageTierChanged(address(this), oldTier, LeverageTierLib.LeverageTier.BASIC, block.timestamp);
        }

        emit PrimeLiquidated(address(this), liquidatedAmount, block.timestamp);
    }
}

contracts/facets/SJoeFacet.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.17;

import "../interfaces/joe-v2/IStableJoeStaking.sol";
import "../interfaces/facets/ISJoeFacet.sol";
import {ReentrancyGuardKeccak} from "../ReentrancyGuardKeccak.sol";
import "../lib/DiamondMethodsAccess.sol";
import "../PrimeAccountModifiers.sol";
import "@uniswap/lib/contracts/libraries/TransferHelper.sol";

contract SJoeFacet is ISJoeFacet, ReentrancyGuardKeccak, DiamondMethodsAccess, PrimeAccountModifiers {
    using TransferHelper for address;

    address private constant SJOE_ADDRESS = 0x1a731B2299E22FbAC282E7094EdA41046343Cb51;
    address private constant REWARD_TOKEN_ADDRESS = 0xB97EF9Ef8734C71904D8002F8b6Bc66Dd9c48a6E; //USDC
    uint256 private constant CLAIMING_FEE = 0.1e18;

    function stakeJoe(uint256 amount) public onlyOwner nonReentrant remainsSolvent noBorrowInTheSameBlock notInLiquidation {
        ITokenManager tokenManager = DeploymentConstants.getTokenManager();
        IERC20Metadata rewardToken = IERC20Metadata(REWARD_TOKEN_ADDRESS);

        IERC20Metadata joe = getERC20TokenInstance('JOE', false);
        require(amount <= joe.balanceOf(address(this)), 'Not enough JOE to stake');

        joe.approve(SJOE_ADDRESS, amount);

        uint256 rewardBalanceBefore = rewardToken.balanceOf(address(this));

        IStableJoeStaking(SJOE_ADDRESS).deposit(amount);

        IStakingPositions.StakedPosition memory position = IStakingPositions.StakedPosition({
            asset: SJOE_ADDRESS,
            symbol: 'JOE',
            identifier: 'sJOE',
            balanceSelector: this.joeBalanceInSJoe.selector,
            unstakeSelector: this.unstakeJoe.selector
        });

        DiamondStorageLib.addStakedPosition(position);

        uint256 rewardBalanceAfter = rewardToken.balanceOf(address(this));

        uint256 claimed = rewardBalanceAfter - rewardBalanceBefore;

        if (claimed > 0){
            DiamondStorageLib.addOwnedAsset(tokenManager.tokenAddressToSymbol(REWARD_TOKEN_ADDRESS), REWARD_TOKEN_ADDRESS);

            uint256 totalTransferred = transferFees(claimed);

            claimed -= totalTransferred;
        }

        emit JoeStaked(msg.sender, 'sJOE', SJOE_ADDRESS, amount, block.timestamp);

        emit ClaimedSJoeRewards(msg.sender, REWARD_TOKEN_ADDRESS, claimed, block.timestamp);
    }

    function unstakeJoe(uint256 amount) public onlyOwnerOrLiquidation nonReentrant noBorrowInTheSameBlock {
        ITokenManager tokenManager = DeploymentConstants.getTokenManager();
        IERC20Metadata rewardToken = IERC20Metadata(REWARD_TOKEN_ADDRESS);

        uint256 rewardBalanceBefore = rewardToken.balanceOf(address(this));

        IStableJoeStaking(SJOE_ADDRESS).withdraw(amount);

        uint256 rewardBalanceAfter = rewardToken.balanceOf(address(this));

        uint256 claimed = rewardBalanceAfter - rewardBalanceBefore;

        if (claimed > 0){
            DiamondStorageLib.addOwnedAsset(tokenManager.tokenAddressToSymbol(REWARD_TOKEN_ADDRESS), REWARD_TOKEN_ADDRESS);

            uint256 totalTransferred = transferFees(claimed);

            claimed -= totalTransferred;
        }

        _syncExposure(tokenManager, REWARD_TOKEN_ADDRESS);

        emit JoeUnstaked(msg.sender, 'sJOE', SJOE_ADDRESS, amount, block.timestamp);

        emit ClaimedSJoeRewards(msg.sender, REWARD_TOKEN_ADDRESS, claimed, block.timestamp);
    }

    function claimSJoeRewards() public onlyOwner nonReentrant remainsSolvent noBorrowInTheSameBlock {
        ITokenManager tokenManager = DeploymentConstants.getTokenManager();

        IERC20Metadata rewardToken = IERC20Metadata(REWARD_TOKEN_ADDRESS);

        uint256 rewardBalanceBefore = rewardToken.balanceOf(address(this));

        IStableJoeStaking(SJOE_ADDRESS).withdraw(0);

        uint256 rewardBalanceAfter = rewardToken.balanceOf(address(this));

        uint256 claimed = rewardBalanceAfter - rewardBalanceBefore;

        if (claimed > 0){
            uint256 totalTransferred = transferFees(claimed);

            claimed -= totalTransferred;

            DiamondStorageLib.addOwnedAsset(tokenManager.tokenAddressToSymbol(REWARD_TOKEN_ADDRESS), REWARD_TOKEN_ADDRESS);
        }

        _syncExposure(tokenManager, REWARD_TOKEN_ADDRESS);

        emit ClaimedSJoeRewards(msg.sender, REWARD_TOKEN_ADDRESS, claimed, block.timestamp);
    }

    function joeBalanceInSJoe() public view returns (uint256 joeBalance)  {
        (joeBalance,) = IStableJoeStaking(SJOE_ADDRESS).getUserInfo(address(this), REWARD_TOKEN_ADDRESS);
    }

    function rewardsInSJoe() public view returns (uint256 rewardsBalance)  {
        rewardsBalance = IStableJoeStaking(SJOE_ADDRESS).pendingReward(address(this), REWARD_TOKEN_ADDRESS);
    }

    function transferFees(uint256 claimed) internal returns (uint256 totalTransferred) {
        ITokenManager tokenManager = DeploymentConstants.getTokenManager();
        IERC20Metadata rewardToken = IERC20Metadata(REWARD_TOKEN_ADDRESS);

        uint256 totalTransferred = CLAIMING_FEE * claimed / 1e18;

        uint256 stabilityPoolTransferAmount = totalTransferred / 3;
        uint256 treasuryTransferAmount = totalTransferred - stabilityPoolTransferAmount;

        bytes32 rewardTokenSymbol = tokenManager.tokenAddressToSymbol(REWARD_TOKEN_ADDRESS);

        address(REWARD_TOKEN_ADDRESS).safeTransfer(DeploymentConstants.getStabilityPoolAddress(), stabilityPoolTransferAmount);
        emit SJoeRewardFeeStabilityPoolTransfer(DeploymentConstants.getStabilityPoolAddress(), rewardTokenSymbol, stabilityPoolTransferAmount, block.timestamp);

        address(REWARD_TOKEN_ADDRESS).safeTransfer(DeploymentConstants.getTreasuryAddress(), treasuryTransferAmount);
        emit SJoeRewardFeeTreasuryTransfer(DeploymentConstants.getTreasuryAddress(), rewardTokenSymbol, treasuryTransferAmount, block.timestamp);
    }
}

contracts/facets/SmartLoanLiquidationFac.content:
// SPDX-License-Identifier: BUSL-1.1
// Last deployed from commit: 56b7ba6f74e4dd5f903aad49110b5db8a353f45f;
pragma solidity 0.8.17;

import "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import "../ReentrancyGuardKeccak.sol";
import "@uniswap/lib/contracts/libraries/TransferHelper.sol";
import "@openzeppelin/contracts/utils/math/Math.sol";
import "../lib/DiamondMethodsAccess.sol";
import "../Pool.sol";
import "../interfaces/ITokenManager.sol";
import "../PrimeAccountModifiers.sol";

//This path is updated during deployment
import "../lib/arbitrum/DeploymentConstants.sol";

import "./avalanche/SolvencyFacetProdAvalanche.sol";
import "../SmartLoanDiamondBeacon.sol";
import "../interfaces/IBorrowersRegistry.sol";
import "../interfaces/facets/ISmartLoanLiquidationFacet.sol";
import "../lib/LeverageTierLib.sol";


contract SmartLoanLiquidationFacet is ISmartLoanLiquidationFacet, ReentrancyGuardKeccak, DiamondMethodsAccess, PrimeAccountModifiers {
    /**
    * Liquidation fee percentages based on leverage tier
    * BASIC: 14% of the repay amount
    * PREMIUM: 7% of the repay amount
    */
    uint256 public constant LIQUIDATION_FEE_PERCENT_BASIC = 140;
    uint256 public constant LIQUIDATION_FEE_PERCENT_PREMIUM = 70;
    uint256 private constant DUST_THRESHOLD_USD = 1e17;

    using TransferHelper for address payable;
    using TransferHelper for address;

    /* ========== VIEW FUNCTIONS ========== */

    /**
     * @return uint256 liquidation fee percentage based on user's leverage tier
    **/
    function getLiquidationFeePercent() public view returns (uint256) {
        LeverageTierLib.LeverageTier currentTier = DiamondStorageLib.getPrimeLeverageTier();

        if (currentTier == LeverageTierLib.LeverageTier.PREMIUM) {
            return LIQUIDATION_FEE_PERCENT_PREMIUM;
        } else {
            // Default to BASIC tier fee (also covers _NON_EXISTENT case)
            return LIQUIDATION_FEE_PERCENT_BASIC;
        }
    }

    /**
     * @dev Check if an address is a whitelisted liquidator
     * @param _liquidator Address to check
     * @return bool True if address is whitelisted
     */
    function isLiquidatorWhitelisted(address _liquidator) public view returns(bool){
        DiamondStorageLib.LiquidationStorage storage ls = DiamondStorageLib.liquidationStorage();
        return ls.canLiquidate[_liquidator];
    }

    /**
    * @dev Returns the timestamp of the last insolvency snapshot
    * @return uint256 Timestamp when the insolvency snapshot was taken (0 if not taken)
    */
    function getLastInsolventTimestamp() external view returns (uint256) {
        DiamondStorageLib.LiquidationSnapshotStorage storage ls = DiamondStorageLib.liquidationSnapshotStorage();
        return ls.lastInsolventTimestamp;
    }

    /**
    * @dev Returns the health ratio from the insolvency snapshot
    * @return uint256 Health ratio when insolvency snapshot was taken
    */
    function getHealthRatioSnapshot() external view returns (uint256) {
        DiamondStorageLib.LiquidationSnapshotStorage storage ls = DiamondStorageLib.liquidationSnapshotStorage();
        return ls.healthRatioSnapshot;
    }

    /* ========== PUBLIC AND EXTERNAL MUTATIVE FUNCTIONS ========== */

    function whitelistLiquidators(address[] memory _liquidators) external onlyOwner {
        address smartLoansFactory = DeploymentConstants.getSmartLoansFactoryAddress();
        DiamondStorageLib.LiquidationStorage storage ls = DiamondStorageLib.liquidationStorage();

        for(uint i; i<_liquidators.length; i++){
            require(IBorrowersRegistry(smartLoansFactory).getLoanForOwner(_liquidators[i])== address(0), "liquidators can't have loans");
            ls.canLiquidate[_liquidators[i]] = true;
            emit LiquidatorWhitelisted(_liquidators[i], msg.sender, block.timestamp);
        }
    }

    function delistLiquidators(address[] memory _liquidators) external onlyOwner {
        DiamondStorageLib.LiquidationStorage storage ls = DiamondStorageLib.liquidationStorage();
        for(uint i; i<_liquidators.length; i++){
            ls.canLiquidate[_liquidators[i]] = false;
            emit LiquidatorDelisted(_liquidators[i], msg.sender, block.timestamp);
        }
    }

    function snapshotInsolvency() external onlyWhitelistedLiquidators accountNotFrozen nonReentrant {
        DiamondStorageLib.LiquidationSnapshotStorage storage ls = DiamondStorageLib.liquidationSnapshotStorage();
        require(ls.lastInsolventTimestamp == 0, "Account is already being liquidated");

        uint256 hr = _getHealthRatio();
        require(hr < 1e18, "Account is solvent");

        ls.lastInsolventTimestamp = block.timestamp;
        ls.healthRatioSnapshot = hr;
        // Capture $-denominated debt at snapshot time. Pre-liquidation swaps may only
        // cause cumulative $-slippage loss up to MAX_CUMULATIVE_LOSS_BPS of this figure.
        ls.debtSnapshotDollars = _getDebt();
        // Defensively zero the cumulative-loss accumulator on every fresh snapshot. The
        // existing clear paths (clearInsolvencySnapshot, liquidate) already wipe it, but
        // this guarantees a new snapshot never inherits a stale loss budget from a prior
        // liquidation cycle.
        delete ls.cumulativeLossDollars;

        emit InsolvencySnapshot(msg.sender, hr, block.timestamp);
    }

    /**
    * @dev Clears the insolvency snapshot when the account becomes solvent again.
    * Can only be called by whitelisted liquidators and requires the account to be solvent.
    */
    function clearInsolvencySnapshot() external onlyWhitelistedLiquidators remainsSolvent accountNotFrozen nonReentrant {
        DiamondStorageLib.LiquidationSnapshotStorage storage ls = DiamondStorageLib.liquidationSnapshotStorage();
        require(ls.lastInsolventTimestamp > 0, "No insolvency snapshot to clear");

        // Clear insolvency snapshot
        delete ls.lastInsolventTimestamp;
        delete ls.healthRatioSnapshot;
        delete ls.debtSnapshotDollars;
        delete ls.cumulativeLossDollars;

        emit InsolvencySnapshotCleared(msg.sender, block.timestamp);
    }

    /**
    * This function fully liquidates an insolvent account after an insolvency snapshot has been taken.
    * All debt is repaid using the account's existing tokens and a liquidation fee is 
    * calculated based on the user's leverage tier (14% for BASIC, 7% for PREMIUM) of the repaid amount.
    * 
    * @param _emergencyMode If true, allows partial debt repayment when account lacks sufficient assets.
    *                       In emergency mode: no liquidation bonus, total account value must be 0 post-liquidation.
    **/
    function liquidate(bool _emergencyMode) 
        external 
        onlyWhitelistedLiquidators 
        accountNotFrozen 
        nonReentrant 
    {
        DiamondStorageLib.LiquidationSnapshotStorage storage ls = DiamondStorageLib.liquidationSnapshotStorage();
        require(ls.lastInsolventTimestamp > 0, "No insolvency snapshot - call snapshotInsolvency first");
        ///@dev the snapshot itself is the proof of insolvency; once a whitelisted liquidator has
        /// taken it, they are entitled to liquidate within the 15-minute window enforced below
        /// regardless of any subsequent price recovery. Re-checking _isSolvent() here would let an
        /// attacker block legitimate liquidation by pumping prices for a single block.
        require(block.timestamp - ls.lastInsolventTimestamp < 15 minutes, "Insolvency snapshot expired - take a new one");

        if (_emergencyMode) {
            _repayAllDebtsPartial();

            uint256 totalValue = _getTotalValue();
            require(totalValue <= DUST_THRESHOLD_USD, "Emergency liquidation requires total account value to be 0");

            // No liquidation fee distribution in emergency mode
        } else {
            uint256 initialDebt = _getDebt();

            _repayAllDebts();

            uint256 remainingDebt = _getDebt();
            require(remainingDebt == 0, "Not all debt was repaid");

            // Use tier-based liquidation fee calculation
            uint256 liquidationFee = initialDebt * getLiquidationFeePercent() / DeploymentConstants.getPercentagePrecision();

            uint256 currentTotalValue = _getTotalValue();

            uint256 actualLiquidationFee = Math.min(liquidationFee, currentTotalValue);

            uint256 percentageToTake = actualLiquidationFee * 1e18 / currentTotalValue;

            if(percentageToTake > 0) {
                _distributeLiquidationFee(percentageToTake);
            }
        }

        // Clear insolvency snapshot
        delete ls.lastInsolventTimestamp;
        delete ls.healthRatioSnapshot;
        delete ls.debtSnapshotDollars;
        delete ls.cumulativeLossDollars;

        // Emit liquidation event
        emit Liquidated(
            msg.sender,
            block.timestamp
        );
    }

    /**
    * @dev Repay all debts of the account using its own assets
    */
    function _repayAllDebts() internal {
        ITokenManager tokenManager = DeploymentConstants.getTokenManager();
        bytes32[] memory debtAssets = tokenManager.getAllPoolAssets();

        for (uint256 i = 0; i < debtAssets.length; i++) {
            IERC20Metadata token = IERC20Metadata(tokenManager.getAssetAddress(debtAssets[i], true));
            Pool pool = Pool(tokenManager.getPoolAddress(debtAssets[i]));

            uint256 debtAmount = pool.getBorrowed(address(this));
            if (debtAmount > 0) {
                uint256 balance = token.balanceOf(address(this));
                require(balance >= debtAmount, "Insufficient token balance to repay debt");

                address(token).safeApprove(address(pool), 0);
                address(token).safeApprove(address(pool), debtAmount);
                pool.repay(debtAmount);

                _syncExposure(tokenManager, address(token));

                emit LiquidationRepay(msg.sender, debtAssets[i], debtAmount, block.timestamp);
            }
        }
    }

    /**
    * @dev Repay debts partially using available balances (for emergency liquidation mode)
    */
    function _repayAllDebtsPartial() internal {
        ITokenManager tokenManager = DeploymentConstants.getTokenManager();
        bytes32[] memory debtAssets = tokenManager.getAllPoolAssets();

        for (uint256 i = 0; i < debtAssets.length; i++) {
            IERC20Metadata token = IERC20Metadata(tokenManager.getAssetAddress(debtAssets[i], true));
            Pool pool = Pool(tokenManager.getPoolAddress(debtAssets[i]));

            uint256 debtAmount = pool.getBorrowed(address(this));
            if (debtAmount > 0) {
                uint256 balance = token.balanceOf(address(this));

                // Repay as much as possible with available balance
                uint256 repayAmount = Math.min(balance, debtAmount);

                if (repayAmount > 0) {
                    address(token).safeApprove(address(pool), 0);
                    address(token).safeApprove(address(pool), repayAmount);
                    pool.repay(repayAmount);

                    _syncExposure(tokenManager, address(token));

                    emit LiquidationRepay(msg.sender, debtAssets[i], repayAmount, block.timestamp);
                }
            }
        }
    }

    /**
    * @dev Distribute the liquidation fee to different treasuries (3-way split)
    */
    function _distributeLiquidationFee(uint256 percentageToTake) internal {
        // Native token transfer (2-way split: 1/3 to stability pool, 2/3 to treasury)
        if (address(this).balance > 0) {
            uint256 transferAmount = address(this).balance * percentageToTake / 1e18;
            uint256 stabilityPoolTransferAmount = transferAmount / 3;
            uint256 treasuryTransferAmount = transferAmount - stabilityPoolTransferAmount;

            if(transferAmount > 3){
                payable(DeploymentConstants.getStabilityPoolAddress()).safeTransferETH(stabilityPoolTransferAmount);
                emit LiquidationTransfer(DeploymentConstants.getStabilityPoolAddress(), DeploymentConstants.getNativeTokenSymbol(), stabilityPoolTransferAmount, block.timestamp);

                payable(DeploymentConstants.getTreasuryAddress()).safeTransferETH(treasuryTransferAmount);
                emit LiquidationFeesTransfer(DeploymentConstants.getTreasuryAddress(), DeploymentConstants.getNativeTokenSymbol(), treasuryTransferAmount, block.timestamp);
            }
        }

        bytes32[] memory assetsOwned = DeploymentConstants.getAllOwnedAssets();
        ITokenManager tokenManager = DeploymentConstants.getTokenManager();

        for (uint256 i; i < assetsOwned.length; i++) {
            IERC20Metadata token = getERC20TokenInstance(assetsOwned[i], true);
            address exposureUpdateAddress = address(token);
            if(address(token) == 0x9e295B5B976a184B14aD8cd72413aD846C299660){
                token = IERC20Metadata(0xaE64d55a6f09E4263421737397D1fdFA71896a69);
            }

            uint256 balance = token.balanceOf(address(this));
            if (balance > 0) {
                uint256 transferAmount = balance * percentageToTake / 1e18;
                uint256 stabilityPoolTransferAmount = transferAmount / 3;
                uint256 treasuryTransferAmount = transferAmount - stabilityPoolTransferAmount;

                if(transferAmount > 3){
                    address(token).safeTransfer(DeploymentConstants.getStabilityPoolAddress(), stabilityPoolTransferAmount);
                    emit LiquidationTransfer(DeploymentConstants.getStabilityPoolAddress(), assetsOwned[i], stabilityPoolTransferAmount, block.timestamp);

                    address(token).safeTransfer(DeploymentConstants.getTreasuryAddress(), treasuryTransferAmount);
                    emit LiquidationFeesTransfer(DeploymentConstants.getTreasuryAddress(), assetsOwned[i], treasuryTransferAmount, block.timestamp);
                }

                _syncExposure(tokenManager, exposureUpdateAddress);
            }
        }
    }
}

contracts/facets/SmartLoanViewFacet.sol.content:
// SPDX-License-Identifier: BUSL-1.1
// Last deployed from commit: 56b7ba6f74e4dd5f903aad49110b5db8a353f45f;
pragma solidity 0.8.17;

import "@uniswap/lib/contracts/libraries/TransferHelper.sol";
import "../Pool.sol";
import {DiamondStorageLib} from "../lib/DiamondStorageLib.sol";
import {LeverageTierLib} from "../lib/LeverageTierLib.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

//This path is updated during deployment
import "../lib/arbitrum/DeploymentConstants.sol";
import "../lib/GmxV2FeesHelper.sol";
import {IGmxReader} from "../interfaces/gmx-v2/IGmxReader.sol";
import "../PrimeAccountModifiers.sol";

contract SmartLoanViewFacet is GmxV2FeesHelper, PrimeAccountModifiers {
    using TransferHelper for address payable;
    using TransferHelper for address;

    struct AssetNameBalance {
        bytes32 name;
        uint256 balance;
    }

    struct AssetNameBalanceDebtCoverage {
        bytes32 name;
        uint256 balance;
        uint256 debtCoverage;
    }

    struct AssetNameDebt {
        bytes32 name;
        uint256 debt;
    }

    struct AssetNamePrice {
        bytes32 name;
        uint256 price;
    }

    /////////////////////
    // ERRORS
    /////////////////////
    error NotGMXMarket();
    error SymbolNotFoundInArray();

    /* ========== PUBLIC AND EXTERNAL MUTATIVE FUNCTIONS ========== */

    function initialize(address owner) external {
        require(owner != address(0), "Initialize: Cannot set the owner to a zero address");
        require(address(this) != DeploymentConstants.getDiamondAddress(), "DiamondInit: Cannot initialize DiamondBeacon");

        DiamondStorageLib.SmartLoanStorage storage sls = DiamondStorageLib.smartLoanStorage();
        require(!sls._initialized, "DiamondInit: contract is already initialized");
        DiamondStorageLib.setContractOwner(owner);
        DiamondStorageLib.setPrimeLeverageTier(LeverageTierLib.LeverageTier.BASIC);
        sls._initialized = true;
    }

    /* ========== VIEW FUNCTIONS ========== */

    function getPercentagePrecision() public view virtual returns (uint256) {
        return DeploymentConstants.getPercentagePrecision();
    }

    function getAccountFrozenSince() public view returns (uint256){
        DiamondStorageLib.SmartLoanStorage storage sls = DiamondStorageLib.smartLoanStorage();
        return sls.frozenSince;
    }

    /**
    * Returns the saved GMX position benchmark for a given market
    * @param market The GMX market address to get benchmark data for
    * @return benchmark The benchmark data including value, token amounts, timestamps, and addresses
    */
    function getGmxPositionBenchmark(address market) external view returns (DiamondStorageLib.GmxPositionBenchmark memory benchmark) {
        return DiamondStorageLib.getGmxPositionBenchmark(market);
    }


    /**
    * Returns a current balance of the asset held by the smart loan
    * @param _asset the code of an asset
    **/
    function getBalance(bytes32 _asset) public view returns (uint256) {
        IERC20 token = IERC20(DeploymentConstants.getTokenManager().getAssetAddress(_asset, true));
        return token.balanceOf(address(this));
    }

    function getAllOwnedAssets() external view returns (bytes32[] memory result) {
        return DeploymentConstants.getAllOwnedAssets();
    }

    function getSupportedTokensAddresses() external view returns (address[] memory) {
        ITokenManager tokenManager = DeploymentConstants.getTokenManager();
        return tokenManager.getSupportedTokensAddresses();
    }

    function getAllAssetsBalancesDebtCoverages() public view returns (AssetNameBalanceDebtCoverage[] memory) {
        ITokenManager tokenManager = DeploymentConstants.getTokenManager();
        bytes32[] memory assets = tokenManager.getAllTokenAssets();
        AssetNameBalanceDebtCoverage[] memory result = new AssetNameBalanceDebtCoverage[](assets.length);

        for (uint256 i = 0; i < assets.length; i++) {
            address assetAddress = tokenManager.getAssetAddress(assets[i], true);
            result[i] = AssetNameBalanceDebtCoverage({
                name : assets[i],
                balance : IERC20(assetAddress).balanceOf(address(this)),
                debtCoverage : tokenManager.tieredDebtCoverage(DiamondStorageLib.getPrimeLeverageTier(), assetAddress)
            });
        }

        return result;
    }


    function getAllAssetsBalances() public view returns (AssetNameBalance[] memory) {
        ITokenManager tokenManager = DeploymentConstants.getTokenManager();
        bytes32[] memory assets = tokenManager.getAllTokenAssets();
        AssetNameBalance[] memory result = new AssetNameBalance[](assets.length);

        // Collect all unique symbols needed for GM tokens
        bytes32[] memory uniqueGMTokensSymbols = _collectGmTokenSymbols(assets, tokenManager);
        uint256[] memory allPrices = uniqueGMTokensSymbols.length > 0 ? getPrices(uniqueGMTokensSymbols) : new uint256[](0);

        // Populate results
        for (uint256 i = 0; i < assets.length; i++) {
            result[i] = _getAssetBalance(assets[i], uniqueGMTokensSymbols, allPrices, tokenManager);
        }

        return result;
    }

    function _collectGmTokenSymbols(
        bytes32[] memory assets,
        ITokenManager tokenManager
    ) internal view returns (bytes32[] memory uniqueGMTokensSymbols) {
        // Temporary storage for collecting unique symbols. 
        // Worst case is all assets are GMX markets with 3 unique symbols each.
        bytes32[] memory allSymbols = new bytes32[](assets.length * 3);
        uint256 symbolCount = 0;

        for (uint256 i = 0; i < assets.length; i++) {
            address assetAddress = tokenManager.getAssetAddress(assets[i], true);
            if (tokenManager.isGmxMarketWhitelisted(assetAddress)) {
                symbolCount = _addGmTokenSymbols(assetAddress, allSymbols, symbolCount, tokenManager);
            }
        }

        // Create final array with exact size
        uniqueGMTokensSymbols = new bytes32[](symbolCount);
        for (uint256 i = 0; i < symbolCount; i++) {
            uniqueGMTokensSymbols[i] = allSymbols[i];
        }
    }

    function _addGmTokenSymbols(
        address gmToken,
        bytes32[] memory allSymbols,
        uint256 currentCount,
        ITokenManager tokenManager
    ) internal view returns (uint256 newCount) {
        // Get market properties
        (address longToken, address shortToken) = _getMarketTokens(gmToken);

        // Get symbols
        bytes32 gmSymbol = tokenManager.tokenAddressToSymbol(gmToken);
        bytes32 longSymbol = tokenManager.tokenAddressToSymbol(longToken);

        newCount = currentCount;

        // Add GM token symbol if not present
        if (!_symbolExists(allSymbols, newCount, gmSymbol)) {
            allSymbols[newCount] = gmSymbol;
            newCount++;
        }

        // Add long token symbol if not present
        if (!_symbolExists(allSymbols, newCount, longSymbol)) {
            allSymbols[newCount] = longSymbol;
            newCount++;
        }

        // Add short token symbol if it's different (not GmxPlus market)
        if (!tokenManager.isGmxPlusMarket(gmToken)) {
            bytes32 shortSymbol = tokenManager.tokenAddressToSymbol(shortToken);
            if (!_symbolExists(allSymbols, newCount, shortSymbol)) {
                allSymbols[newCount] = shortSymbol;
                newCount++;
            }
        }
    }

    // Just getting the underlying token addresses.
    function _getMarketTokens(address gmToken) internal view returns (address longToken, address shortToken) {
        address gmxReader = DeploymentConstants.getGmxReaderAddress();
        address dataStore = DeploymentConstants.getGmxDataStoreAddress();
        IGmxReader.MarketProps memory marketProps = IGmxReader(gmxReader).getMarket(dataStore, gmToken);
        longToken = marketProps.longToken;
        shortToken = marketProps.shortToken;
        if (longToken == address(0)) revert NotGMXMarket();
    }

    // Getting balance for a single asset, handling GMX markets with fee deductions. 
    // Prices are passed in to avoid multiple redundant fetches.
    function _getAssetBalance(
        bytes32 assetName,
        bytes32[] memory uniqueGMTokensSymbols,
        uint256[] memory allPrices,
        ITokenManager tokenManager
    ) internal view returns (AssetNameBalance memory) {
        address assetAddress = tokenManager.getAssetAddress(assetName, true);

        if (tokenManager.isGmxMarketWhitelisted(assetAddress)) {
            return AssetNameBalance({
                name: assetName,
                balance: _getGmTokenBalanceAfterFeesWithPrices(assetAddress, uniqueGMTokensSymbols, allPrices)
            });
        } else {
            return AssetNameBalance({
                name: assetName,
                balance: IERC20(assetAddress).balanceOf(address(this))
            });
        }
    }

    // helper function to check if a symbol already exists in the array
    function _symbolExists(bytes32[] memory symbols, uint256 length, bytes32 symbol) private pure returns (bool) {
        for (uint256 i = 0; i < length; i++) {
            if (symbols[i] == symbol) {
                return true;
            }
        }
        return false;
    }

    // helper function to find the index of a symbol in the array
    function _findPriceIndex(bytes32[] memory symbols, bytes32 targetSymbol) private pure returns (uint256) {
        for (uint256 i = 0; i < symbols.length; i++) {
            if (symbols[i] == targetSymbol) {
                return i;
            }
        }
        revert SymbolNotFoundInArray();
    }

    function _getGmTokenBalanceAfterFeesWithPrices(
        address gmToken,
        bytes32[] memory allSymbols,
        uint256[] memory allPrices
    ) internal view returns (uint256) {
        // Get market tokens
        (address longToken, address shortToken) = _getMarketTokens(gmToken);

        // Get token manager
        ITokenManager tokenManager = DeploymentConstants.getTokenManager();

        // Get prices for this GM token
        (uint256 gmPrice, uint256 longPrice, uint256 shortPrice) = _getGmTokenPrices(
            gmToken, longToken, shortToken, allSymbols, allPrices, tokenManager
        );

        // Calculate fees and balance
        uint256 feeInGmTokens = _getDeductibleFeesInGmTokens(gmToken, gmPrice, longPrice, shortPrice);
        uint256 balance = IERC20(gmToken).balanceOf(address(this));

        return feeInGmTokens >= balance ? 0 : balance - feeInGmTokens;
    }

    function _getGmTokenPrices(
        address gmToken,
        address longToken,
        address shortToken,
        bytes32[] memory allSymbols,
        uint256[] memory allPrices,
        ITokenManager tokenManager
    ) internal view returns (uint256 gmPrice, uint256 longPrice, uint256 shortPrice) {
        // Get symbols
        bytes32 gmSymbol = tokenManager.tokenAddressToSymbol(gmToken);
        bytes32 longSymbol = tokenManager.tokenAddressToSymbol(longToken);

        // Find prices from pre-fetched array
        gmPrice = allPrices[_findPriceIndex(allSymbols, gmSymbol)];
        longPrice = allPrices[_findPriceIndex(allSymbols, longSymbol)];

        if (tokenManager.isGmxPlusMarket(gmToken)) {
            shortPrice = 0; // Avoid double counting for GmxPlus markets
        } else {
            bytes32 shortSymbol = tokenManager.tokenAddressToSymbol(shortToken);
            shortPrice = allPrices[_findPriceIndex(allSymbols, shortSymbol)];
        }
    }

    // Redefining and keeping this function for backward compatibility
    function getGmTokenBalanceAfterFees(address gmToken) external view returns (uint256) {
        // Get market tokens
        (address longToken, address shortToken) = _getMarketTokens(gmToken);

        // Get token manager
        ITokenManager tokenManager = DeploymentConstants.getTokenManager();
        uint256[] memory prices;
        uint256 feeInGmTokens;
        if(!tokenManager.isGmxPlusMarket(gmToken)) {
            bytes32[] memory symbols = new bytes32[](3);
            symbols[0] = tokenManager.tokenAddressToSymbol(gmToken);
            symbols[1] = tokenManager.tokenAddressToSymbol(longToken);
            symbols[2] = tokenManager.tokenAddressToSymbol(shortToken);
            prices = getPrices(symbols);
            feeInGmTokens = _getDeductibleFeesInGmTokens(gmToken, prices[0], prices[1], prices[2]);
        } else {
            bytes32[] memory symbols = new bytes32[](2);
            symbols[0] = tokenManager.tokenAddressToSymbol(gmToken);
            symbols[1] = tokenManager.tokenAddressToSymbol(longToken);
            prices = getPrices(symbols);
            feeInGmTokens = _getDeductibleFeesInGmTokens(gmToken, prices[0], prices[1], 0);
        }
        // Calculate fees and balance
        uint256 balance = IERC20(gmToken).balanceOf(address(this));

        return feeInGmTokens >= balance ? 0 : balance - feeInGmTokens;
    }

    function getDebts() public view returns (AssetNameDebt[] memory) {
        ITokenManager tokenManager = DeploymentConstants.getTokenManager();
        bytes32[] memory assets = tokenManager.getAllPoolAssets();
        AssetNameDebt[] memory result = new AssetNameDebt[](assets.length);

        for (uint256 i = 0; i < assets.length; i++) {
            Pool pool = Pool(tokenManager.getPoolAddress(assets[i]));

            result[i] = AssetNameDebt({
            name : assets[i],
            debt : pool.getBorrowed(address(this))
            });
        }

        return result;
    }

    /**
     * Returns the prices of all assets supported by the TokenManager
     * It could be used as a helper method for UI
     * @dev This function uses the redstone-evm-connector
     **/
    function getAllAssetsPrices() public returns (AssetNamePrice[] memory) {
        bytes32[] memory assets = DeploymentConstants.getTokenManager().getAllTokenAssets();
        uint256[] memory prices = DiamondMethodsAccess.getPrices(assets);
        AssetNamePrice[] memory result = new AssetNamePrice[](assets.length);
        for (uint i = 0; i < assets.length; i++) {
            result[i] = AssetNamePrice({
                name : assets[i],
                price : prices[i]
            });
        }
        return result;
    }

    function getContractOwner() external view returns (address _owner) {
        _owner = DiamondStorageLib.contractOwner();
    }

    function getProposedOwner() external view returns (address _proposed) {
        _proposed = DiamondStorageLib.proposedOwner();
    }

    function getStakedPositions() external view returns (IStakingPositions.StakedPosition[] memory  _positions) {
        _positions = DiamondStorageLib.stakedPositions();
    }
}

contracts/facets/SmartLoanWrappedNativeT.content:
// SPDX-License-Identifier: BUSL-1.1
// Last deployed from commit: 56b7ba6f74e4dd5f903aad49110b5db8a353f45f;
pragma solidity 0.8.17;

import "@openzeppelin/contracts/utils/math/Math.sol";
import "@uniswap/lib/contracts/libraries/TransferHelper.sol";
import "../interfaces/IWrappedNativeToken.sol";
import "../lib/DiamondMethodsAccess.sol";
import "../PrimeAccountModifiers.sol";
import "../ReentrancyGuardKeccak.sol";

//This path is updated during deployment
import "../lib/arbitrum/DeploymentConstants.sol";

contract SmartLoanWrappedNativeTokenFacet is DiamondMethodsAccess, PrimeAccountModifiers, ReentrancyGuardKeccak {
    using TransferHelper for address payable;

    function wrapNativeToken(uint256 amount) onlyOwnerOrLiquidation nonReentrant public {
        require(amount <= address(this).balance, "Not enough native token to wrap");
        require(amount > 0, "Cannot wrap 0 tokens");
        IWrappedNativeToken wrapped = IWrappedNativeToken(DeploymentConstants.getNativeToken());
        wrapped.deposit{value : amount}();

        ITokenManager tokenManager = DeploymentConstants.getTokenManager();
        _syncExposure(tokenManager, address(wrapped));

        emit WrapNative(msg.sender, amount, block.timestamp);
    }

    function depositNativeToken() public payable virtual onlyOwner {
        IWrappedNativeToken wrapped = IWrappedNativeToken(DeploymentConstants.getNativeToken());
        wrapped.deposit{value : msg.value}();

        ITokenManager tokenManager = DeploymentConstants.getTokenManager();
        _syncExposure(tokenManager, address(wrapped));

        emit DepositNative(msg.sender, msg.value, block.timestamp);
    }


    /* ========== EVENTS ========== */

    /**
    * @dev emitted when native tokens are wrapped in the SmartLoan
    * @param user the address initiating wrap
    * @param amount of wrapped funds
    * @param timestamp of wrap
    **/
    event WrapNative(address indexed user, uint256 amount, uint256 timestamp);

    /**
    * @dev emitted when native tokens are deposited to the SmartLoan
    * @param user the address initiating deposit of native token
    * @param amount of deposited funds
    * @param timestamp of deposit
    **/
    event DepositNative(address indexed user, uint256 amount, uint256 timestamp);

    /**
    * @dev emitted when native tokens are unwrapped and withdrawn from the SmartLoan
    * @param user the address initiating unwrap and withdraw of native token
    * @param amount of unwrapped and withdrawn funds
    * @param timestamp of unwrap and withdraw
    **/
    event UnwrapAndWithdraw(address indexed user, uint256 amount, uint256 timestamp);

}

contracts/facets/SolvencyFacetProd.sol.content:
// SPDX-License-Identifier: BUSL-1.1
// Last deployed from commit: ecd675d46c3f696de7562f6be071a442d97f37d9;
pragma solidity 0.8.17;

import "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@redstone-finance/evm-connector/contracts/data-services/PrimaryProdDataServiceConsumerBase.sol";
import "@openzeppelin/contracts/utils/math/Math.sol";
import "../interfaces/ITokenManager.sol";
import "../Pool.sol";
import "../DiamondHelper.sol";
import "../interfaces/IStakingPositions.sol";
import "../interfaces/facets/avalanche/ITraderJoeV2Facet.sol";
import {PriceHelper} from "../lib/joe-v2/PriceHelper.sol";
import {Uint256x256Math} from "../lib/joe-v2/math/Uint256x256Math.sol";
import {AggregatorV3Interface} from "@chainlink/contracts/src/v0.8/shared/interfaces/AggregatorV3Interface.sol";
import {DiamondStorageLib} from "../lib/DiamondStorageLib.sol";
import {GmxBenchmarkMath} from "../lib/GmxBenchmarkMath.sol";

//This path is updated during deployment
import "../lib/arbitrum/DeploymentConstants.sol";

abstract contract SolvencyFacetProd is PrimaryProdDataServiceConsumerBase, DiamondHelper {
    using PriceHelper for uint256;
    using Uint256x256Math for uint256;

    struct AssetPrice {
        bytes32 asset;
        uint256 price;
    }

    // Struct used in the liquidation process to obtain necessary prices only once
    struct CachedPrices {
        AssetPrice[] ownedAssetsPrices;
        AssetPrice[] debtAssetsPrices;
        AssetPrice[] stakedPositionsPrices;
        AssetPrice[] assetsToRepayPrices;
        // Prices of TraderJoe V2 bin tokens (tokenX / tokenY) that may not be in ownedAssets.
        AssetPrice[] tjv2TokenPrices;
    }

    struct PriceInfo {
        address tokenX;
        address tokenY;
        uint256 priceX;
        uint256 priceY;
    }

    ////////////////////////////////////////////////////////////////////////
    /////////// Chainlink Integration Methods //////////////////////////////
    ////////////////////////////////////////////////////////////////////////

    ///@dev updated to 25 hours
    uint256 private constant CHAINLINK_MAX_DELAY = 6 hours;


    // Struct to track pricing request info
    struct PriceRequest {
        bool useDirect;              // True if using Redstone directly 
        bytes32 directSymbol;        // If useDirect is true, the token symbol to request.
        address chainlinkFeed;       // If useDirect is false, the chainlink feed address for ChainLink.
    }

    /**
    * @notice Retrieves prices for an array of token symbols using Redstone or Chainlink oracles
    * @dev Determines oracle source per token, batches Redstone calls, fetches Chainlink individually
    * @param symbols Array of asset symbols to get prices for
    * @return finalPrices Array of prices corresponding to input symbols, normalized to 8 decimals
    */
    function getPricesFromRedstoneAndChainlink(bytes32[] memory symbols) public view returns (uint256[] memory finalPrices) {
        ITokenManager tokenManager = DeploymentConstants.getTokenManager();
        uint256 n = symbols.length;
        PriceRequest[] memory requests = new PriceRequest[](n);
        uint256 totalSymbolsCount = 0; // Upper bound for total symbols needed

        // Pass 1: Build a request for each token.
        for (uint256 i = 0; i < n; i++) {
            address tokenAddr = tokenManager.getAssetAddress(symbols[i], true);

            // Check if Chainlink feed exists for this token
            address feedAddress = tokenManager.getChainlinkFeed(tokenAddr);
            bool isConfigured = feedAddress != address(0);
            if (isConfigured) {
                try tokenManager.getPoolAddress(symbols[i]) {
                    revert BorrowableAssetRedstoneRequired(symbols[i]);
                } catch {} 

                    // Chainlink is configured and asset is not borrowable, use Chainlink
                    requests[i] = PriceRequest({
                        useDirect: false,
                        directSymbol: 0,
                        chainlinkFeed: feedAddress
                    });

            } else {
                // Not configured: use the input symbol directly via Redstone
                bytes32 requestSymbol = symbols[i];
                requests[i] = PriceRequest({
                    useDirect: true,
                    directSymbol: requestSymbol,
                    chainlinkFeed: address(0)
                });
                totalSymbolsCount+=1;
            }
        }

        // Pass 2: Build a global unique list of Redstone symbols.
        bytes32[] memory globalSymbolsTemp = new bytes32[](totalSymbolsCount);
        uint256 globalCount = 0;
        for (uint256 i = 0; i < n; i++) {
            if (requests[i].useDirect) {
                bytes32 sym = requests[i].directSymbol;
                // Check for duplicates
                if (!contains(globalSymbolsTemp, globalCount, sym)) {
                    globalSymbolsTemp[globalCount] = sym;
                    globalCount++;
                }
            }
        }

        bytes32[] memory globalUniqueSymbols = new bytes32[](globalCount);
        for (uint256 i = 0; i < globalCount; i++) {
            globalUniqueSymbols[i] = globalSymbolsTemp[i];

        }

        // --- Pass 3: Retrieve prices for all unique symbols in one call using Redstone ---
        uint256[] memory globalPrices = getOracleNumericValuesWithDuplicatesFromTxMsg(globalUniqueSymbols); 

        // Pass 4: Assemble final prices per input token.
        finalPrices = new uint256[](n);
        for (uint256 i = 0; i < n; i++) {
            if (requests[i].useDirect) {
                uint256 index = findIndex(globalUniqueSymbols, requests[i].directSymbol);
                // Redstone prices are already in 8 decimals
                finalPrices[i] = globalPrices[index];
            } else {
                // getChainlinkPrice returns price normalized to 8 decimals
                finalPrices[i] = getChainlinkPrice(requests[i].chainlinkFeed);
            }
        }
        return finalPrices;
    }

    /**
    * @notice Fetches price from Chainlink feed and normalizes to 8 decimals
    * @param feedAddress Address of the Chainlink price feed
    * @return price Price normalized to 8 decimals
    */
    function getChainlinkPrice(address feedAddress) internal view returns (uint256 price) {
        AggregatorV3Interface priceFeed = AggregatorV3Interface(feedAddress);

        (
            uint80 roundId,
            int256 answer,
            /* uint256 startedAt */,
            uint256 updatedAt,
            uint80 answeredInRound
        ) = priceFeed.latestRoundData();

        // Validate Chainlink response
        if (answer <= 0) revert ChainlinkWrongPrice();
        if (answeredInRound < roundId) revert ChainlinkStaleRound();
        if (updatedAt == 0) revert ChainlinkIncompleteRound();
        ///@dev can get rid of this check if this is an overkill. Different feeds have highly varied heartbeats
        if (block.timestamp - updatedAt > CHAINLINK_MAX_DELAY) revert ChainlinkStaleData();

        // Get feed decimals and normalize to 8 decimals
        uint8 feedDecimals = priceFeed.decimals();

        if (feedDecimals > 36) revert ChainlinkWrongDecimals(); ///@dev should never happen

        if (feedDecimals < 8) {
            // Scale up to 8 decimals
            price = uint256(answer) * (10 ** (8 - feedDecimals));
        } else if (feedDecimals > 8) {
            // Scale down to 8 decimals
            price = uint256(answer) / (10 ** (feedDecimals - 8));
        } else {
            // Already 8 decimals
            price = uint256(answer);
        }

        return price;
    }

    /**
    * @notice Helper function to check if a symbol exists in an array
    * @param array Array to search in
    * @param length Current length of valid elements
    * @param symbol Symbol to search for
    * @return bool True if symbol exists
    */
    function contains(bytes32[] memory array, uint256 length, bytes32 symbol) internal pure returns (bool) {
        for (uint256 i = 0; i < length; i++) {
            if (array[i] == symbol) {
                return true;
            }
        }
        return false;
    }

    /**
    * @notice Helper function to find index of a symbol in an array
    * @param array Array to search in
    * @param symbol Symbol to find
    * @return uint256 Index of the symbol
    */
    function findIndex(bytes32[] memory array, bytes32 symbol) internal pure returns (uint256) {
        for (uint256 i = 0; i < array.length; i++) {
            if (array[i] == symbol) {
                return i;
            }
        }
        revert SymbolNotFound(symbol);
    }

    /**
    * @notice Helper function to find a price from the CachedPrices struct
    * @param cachedPrices The struct containing all pre-fetched price arrays
    * @param symbol The asset symbol to find
    * @return price The price of the symbol
    */
    function findPriceInCachedPrices(CachedPrices memory cachedPrices, bytes32 symbol) internal pure returns (uint256 price) {
        // Search owned assets (most likely)
        for (uint256 i = 0; i < cachedPrices.ownedAssetsPrices.length; i++) {
            if (cachedPrices.ownedAssetsPrices[i].asset == symbol) {
                return cachedPrices.ownedAssetsPrices[i].price;
            }
        }
        // Search debt assets
        for (uint256 i = 0; i < cachedPrices.debtAssetsPrices.length; i++) {
            if (cachedPrices.debtAssetsPrices[i].asset == symbol) {
                return cachedPrices.debtAssetsPrices[i].price;
            }
        }
        // Search staked assets
        for (uint256 i = 0; i < cachedPrices.stakedPositionsPrices.length; i++) {
            if (cachedPrices.stakedPositionsPrices[i].asset == symbol) {
                return cachedPrices.stakedPositionsPrices[i].price;
            }
        }
        // Search repay assets (in case it was passed in during liquidation)
        for (uint256 i = 0; i < cachedPrices.assetsToRepayPrices.length; i++) {
            if (cachedPrices.assetsToRepayPrices[i].asset == symbol) {
                return cachedPrices.assetsToRepayPrices[i].price;
            }
        }
        // Search TJv2 bin-token prices (tokenX / tokenY that are not in ownedAssets)
        for (uint256 i = 0; i < cachedPrices.tjv2TokenPrices.length; i++) {
            if (cachedPrices.tjv2TokenPrices[i].asset == symbol) {
                return cachedPrices.tjv2TokenPrices[i].price;
            }
        }
        revert SymbolNotFound(symbol);
    }


