// SPDX-License-Identifier: BUSL-1.1
// Last deployed from commit: a52a9854d08c0ef6be5d121511952dd473bb82dd;
pragma solidity 0.8.17;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IERC20Metadata} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import {TransferHelper} from "@uniswap/lib/contracts/libraries/TransferHelper.sol";
import {ReentrancyGuardKeccak} from "../ReentrancyGuardKeccak.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {DiamondStorageLib} from "../lib/DiamondStorageLib.sol";
import {ITokenManager} from "../interfaces/ITokenManager.sol";
import {IStakingPositions} from "../interfaces/IStakingPositions.sol";
import {Pool} from "../Pool.sol";
import {PrimeAccountModifiers} from "../PrimeAccountModifiers.sol";
import {SmartLoanLiquidationFacet} from "./SmartLoanLiquidationFacet.sol";
import {IAssetsOperationsFacet} from "../interfaces/facets/IAssetsOperationsFacet.sol";
import {ParaSwapHelper} from "../lib/ParaSwapHelper.sol";

//this path is updated during deployment
import {DeploymentConstants} from "../lib/arbitrum/DeploymentConstants.sol";

/**
 * @title SwapDebtFacet
 * @notice Facet for refinancing debt from one token to another while maintaining equal dollar value
 * @dev Allows users to convert their existing debt (e.g., USDC) into an equivalent value of debt in another token (e.g., BTC)
 * without changing their overall debt position value, using ParaSwap for efficient token conversion
 */
contract SwapDebtFacet is ReentrancyGuardKeccak, PrimeAccountModifiers, ParaSwapHelper {

    using TransferHelper for address payable;
    using TransferHelper for address;

    /**
     * @dev emitted after a debt swap
     * @param user the address which performed the debt swap
     * @param fromToken token that was repaid
     * @param toToken token that was borrowed
     * @param repayAmount the amount of fromToken that was repaid
     * @param borrowAmount the amount of toToken that was borrowed
     * @param timestamp time of debt swap
     **/
    event DebtSwap(address indexed user, address indexed fromToken, address indexed toToken, uint256 repayAmount, uint256 borrowAmount, uint256 timestamp);


       /**
     * @notice Processes the repayment after a debt refinancing
     * @dev Handles approval, repayment, and exposure adjustments after converting debt to a new token
     * @param tokenManager The token manager interface
     * @param fromAssetPool The pool where the original debt is being repaid
     * @param fromToken The original debt token address being repaid
     * @param repayAmount The amount to repay
     */
    function _processRepay(ITokenManager tokenManager, Pool fromAssetPool, address fromToken, uint256 repayAmount) internal {
        fromToken.safeApprove(address(fromAssetPool), 0);
        fromToken.safeApprove(address(fromAssetPool), repayAmount);
        fromAssetPool.repay(repayAmount);
        _syncExposure(tokenManager, fromToken);
        fromToken.safeApprove(address(fromAssetPool), 0);
    }

  /**
     * @notice Refinances debt from one token to another of equal dollar value
     * @dev Borrows in the new token, swaps to the old token, and repays existing debt
     * @param _fromAsset Asset symbol of the current debt to be repaid
     * @param _toAsset Asset symbol of the new debt to take on
     * @param _repayAmount Amount of current debt to repay
     * @param _borrowAmount Amount of new token to borrow
     * @param selector Function selector for the ParaSwap transaction
     * @param data Calldata to execute with ParaSwap
     */    
     function swapDebtParaSwap(bytes32 _fromAsset, bytes32 _toAsset, uint256 _repayAmount, uint256 _borrowAmount, bytes4 selector, bytes calldata data) external onlyOwner noBorrowInTheSameBlock remainsSolvent nonReentrant notInLiquidation {
        require(_borrowAmount > 0, "Borrow amount must be positive");
        require(_fromAsset != _toAsset, "Cannot swap same asset");

        ITokenManager tokenManager = DeploymentConstants.getTokenManager();
        Pool fromAssetPool = Pool(tokenManager.getPoolAddress(_fromAsset));
        _repayAmount = Math.min(_repayAmount, fromAssetPool.getBorrowed(address(this)));

        IERC20Metadata toToken = getERC20TokenInstance(_toAsset, false);
        IERC20Metadata fromToken = getERC20TokenInstance(_fromAsset, false);

        // Check dollar value difference between borrowed and repaid amounts
        {
            bytes32[] memory symbols = new bytes32[](2);
            symbols[0] = _fromAsset;
            symbols[1] = _toAsset;
            uint256[] memory prices = getPrices(symbols);

            uint256 repayValueUSD = prices[0] * _repayAmount * (10**10) / (10**fromToken.decimals());
            uint256 borrowValueUSD = prices[1] * _borrowAmount * (10**10) / (10**toToken.decimals());

            // Allow maximum 5% difference between repay and borrow values
            uint256 maxDiff = repayValueUSD > borrowValueUSD ? 
                ((repayValueUSD - borrowValueUSD) * 10000) / repayValueUSD : 
                ((borrowValueUSD - repayValueUSD) * 10000) / borrowValueUSD;

            require(maxDiff <= 500, "Dollar value diff too high"); // 500 = 5%
        }

        Pool toAssetPool = Pool(tokenManager.getPoolAddress(_toAsset));
        toAssetPool.borrow(_borrowAmount);

        uint256 initialRepayTokenAmount = _getAvailableBalance(_fromAsset);

        // Update lastBorrowTimestamp to prevent flash loan attacks
        {
            DiamondStorageLib.DiamondStorage storage ds = DiamondStorageLib.diamondStorage();
            ds._lastBorrowTimestamp = block.timestamp;
        }


        {
            ParaSwapDecodedData memory paraSwapDecodedData = decodeParaSwapData(selector, data);
            require(paraSwapDecodedData.fromAmount == _borrowAmount, "Borrow amount mismatch in swap data");

            validateSwapParameters(paraSwapDecodedData, false);

            SwapTokensDetails memory details = getInitialTokensDetails(
                    paraSwapDecodedData.srcToken,
                    paraSwapDecodedData.destToken
                );

            executeSwap(selector, data, details, paraSwapDecodedData, false);
        }

        _repayAmount = Math.min(_getAvailableBalance(_fromAsset), _repayAmount);

        ///@dev might need to declare a separate scope here if stack too deep error in testing. Compiles now with via_ir
        _processRepay(tokenManager, fromAssetPool, address(fromToken), _repayAmount);
        _syncExposure(tokenManager, address(toToken));

        emit DebtSwap(msg.sender, address(fromToken), address(toToken), _repayAmount, _borrowAmount, block.timestamp);
    }

}

contracts/facets/TraderJoeV2Facet.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.17;

import "../PrimeAccountModifiers.sol";
import "../ReentrancyGuardKeccak.sol";
import "../lib/DiamondMethodsAccess.sol";
import "../interfaces/IWrappedNativeToken.sol";
import "../interfaces/joe-v2/ILBFactory.sol";
import "../interfaces/joe-v2/ILBHookLens.sol";
import "../interfaces/joe-v2/ILBHooksBaseRewarder.sol";
import "../interfaces/joe-v2/ILBRouter.sol";
import "../interfaces/joe-v2/IRewarder.sol";
import "../interfaces/ITokenManager.sol";

//This path is updated during deployment
import "../lib/arbitrum/DeploymentConstants.sol";
import {DiamondStorageLib} from "../lib/DiamondStorageLib.sol";

abstract contract TraderJoeV2Facet is ITraderJoeV2Facet, ReentrancyGuardKeccak, DiamondMethodsAccess, PrimeAccountModifiers {
    using TransferHelper for address payable;
    using TransferHelper for address;

    address private constant REWARDER = 0x624C5b9BEB13af6893e715932c26e2b7A59c410a;

    function maxBinsPerPrimeAccount() public view virtual returns (uint256);

    function getJoeV2RouterAddress() public view virtual returns (address){
        return 0xb4315e873dBcf96Ffd0acd8EA43f689D8c20fB30;
    }

    function getJoeV2LBHookLens() public view virtual returns (address){
        return 0x6124086B90AB910038E607aa1BDD67b284C31c98;
    }

    function getOwnedTraderJoeV2Bins() public view returns (TraderJoeV2Bin[] memory result){
        return DiamondStorageLib.getTjV2OwnedBinsView();
    }

    function getOwnedTraderJoeV2BinsStorage() internal returns (TraderJoeV2Bin[] storage result){
        return DiamondStorageLib.getTjV2OwnedBins();
    }

    function getWhitelistedTraderJoeV2Pairs() internal view virtual returns (ILBPair[] memory pools);

    function isPairWhitelisted(address pair) internal view virtual returns (bool) {
        ILBPair[] memory pairs = getWhitelistedTraderJoeV2Pairs();

        for (uint i; i < pairs.length; ++i) {
            if (pair == address(pairs[i])) return true;
        }
        return false;
    }

    function isRouterWhitelisted(address router) internal view virtual returns (bool) {
        address[] memory routers = new address[](2);
        // Trader Joe V2.1
        routers[0] = 0xb4315e873dBcf96Ffd0acd8EA43f689D8c20fB30;
        // Trader Joe V2.2
        routers[1] = 0x18556DA13313f3532c54711497A8FedAC273220E;

        for (uint i; i < routers.length; ++i) {
            if (router == routers[i]) return true;
        }
        return false;
    }

    function _removeLiquidity(ILBRouter traderJoeV2Router, RemoveLiquidityParameters memory parameters) internal returns (uint256, uint256){
        (uint amountX, uint256 amountY) = traderJoeV2Router.removeLiquidity(
            parameters.tokenX, parameters.tokenY, parameters.binStep, parameters.amountXMin, parameters.amountYMin, parameters.ids, parameters.amounts, address(this), parameters.deadline
        );
        return (amountX, amountY);
    }

    function wrapNativeToken() internal {
        uint256 balance = address(this).balance;
        if(balance > 0){
            IWrappedNativeToken nativeToken = IWrappedNativeToken(DeploymentConstants.getNativeToken());
            nativeToken.deposit{value : balance}();
            ITokenManager tokenManager = DeploymentConstants.getTokenManager();
            _syncExposure(tokenManager, address(nativeToken));
        }
    }

    function claimReward(IRewarder.MerkleEntry[] calldata merkleEntries) external nonReentrant onlyOwner  noBorrowInTheSameBlock remainsSolvent {
        wrapNativeToken();

        uint256 length = merkleEntries.length;
        IERC20[] memory tokens = new IERC20[](length);
        uint256[] memory beforeBalances = new uint256[](length);
        ITokenManager tokenManager = DeploymentConstants.getTokenManager();
        for (uint256 i; i != length; ++i) {
            tokens[i] = merkleEntries[i].token;
            // Add handling for native token case
            beforeBalances[i] = address(tokens[i]) == address(0)
                ? address(this).balance
                : _getAvailableBalance(tokenManager.tokenAddressToSymbol(address(tokens[i])));
        }

        IRewarder rewarder = IRewarder(REWARDER);
        rewarder.batchClaim(merkleEntries);

        for (uint256 i; i != length; ++i) {
            uint256 newBalance;
            if (address(tokens[i]) == address(0)) {
                // For native token
                newBalance = address(this).balance;
                if (newBalance > beforeBalances[i]) {
                    wrapNativeToken();  // This will handle increasing exposure
                }
            } else {
                // For ERC20 tokens
                newBalance = _getAvailableBalance(tokenManager.tokenAddressToSymbol(address(tokens[i])));
                if (newBalance > beforeBalances[i]) {
                    ITokenManager tokenManager = DeploymentConstants.getTokenManager();
                    if(tokenManager.isTokenAssetActive(address(tokens[i]))) {
                        _syncExposure(tokenManager, address(tokens[i]));
                    }
                }
            }
        }
    }

    function claimReward(ILBPair pair, uint256[] calldata ids) external nonReentrant onlyOwner noBorrowInTheSameBlock remainsSolvent{
        wrapNativeToken();
        require(isPairWhitelisted(address(pair)), "TraderJoeV2PoolNotWhitelisted");
        ILBHookLens lbHookLens = ILBHookLens(getJoeV2LBHookLens());
        ILBHookLens.Parameters memory hookLens = lbHookLens.getHooks(address(pair));
        address baseRewarder = hookLens.hooks;
        ITokenManager tokenManager = DeploymentConstants.getTokenManager();

        if(baseRewarder == address(0)) revert TraderJoeV2NoRewardHook();

        address rewardToken = address(ILBHooksBaseRewarder(baseRewarder).getRewardToken());
        bool isNative = (rewardToken == address(0));
        uint256 beforeBalance = isNative ? address(this).balance : _getAvailableBalance(tokenManager.tokenAddressToSymbol(rewardToken));

        ILBHooksBaseRewarder(baseRewarder).claim(address(this), ids);

        uint256 reward = isNative ? address(this).balance - beforeBalance : _getAvailableBalance(tokenManager.tokenAddressToSymbol(rewardToken)) - beforeBalance;

        if(reward > 0) {
            if(isNative) {
                wrapNativeToken();
            } else {
                ITokenManager tokenManager = DeploymentConstants.getTokenManager();
                if(tokenManager.isTokenAssetActive(rewardToken)){
                    _syncExposure(tokenManager, rewardToken);
                }
            }
        }
    }

    function fundLiquidityTraderJoeV2(ILBPair pair, uint256[] memory ids, uint256[] memory amounts) external onlyOwner noBorrowInTheSameBlock nonReentrant notInLiquidation {
        if (!isPairWhitelisted(address(pair))) revert TraderJoeV2PoolNotWhitelisted();

        for (uint256 i; i < ids.length; ++i) {
            if (ids[i] > type(uint24).max) revert IdOutOfRange();
        }

        pair.batchTransferFrom(msg.sender, address(this), ids, amounts);

        TraderJoeV2Bin[] storage ownedBins = getOwnedTraderJoeV2BinsStorage();

        for (uint256 i; i < ids.length; ++i) {
            bool userHadBin;

            for (int256 j; uint(j) < ownedBins.length; ++j) {
                if (address(ownedBins[uint(j)].pair) == address(pair)
                    && ownedBins[uint(j)].id == ids[i]
                ) {
                    userHadBin = true;
                    break;
                }
            }

            if (!userHadBin) {
                ownedBins.push(TraderJoeV2Bin(pair, uint24(ids[i])));
            }
        }

        if (maxBinsPerPrimeAccount() > 0 && ownedBins.length > maxBinsPerPrimeAccount()) revert TooManyBins();

        emit FundedLiquidityTraderJoeV2(msg.sender, address(pair), ids, amounts, block.timestamp);
    }

    function addLiquidityTraderJoeV2(ILBRouter traderJoeV2Router, ILBRouter.LiquidityParameters memory liquidityParameters) external nonReentrant onlyOwner noBorrowInTheSameBlock remainsSolvent notInLiquidation {
        if (!isRouterWhitelisted(address(traderJoeV2Router))) revert TraderJoeV2RouterNotWhitelisted();
        TraderJoeV2Bin[] storage ownedBins = getOwnedTraderJoeV2BinsStorage();
        ILBFactory lbFactory = traderJoeV2Router.getFactory();
        ILBFactory.LBPairInformation memory pairInfo = lbFactory.getLBPairInformation(liquidityParameters.tokenX, liquidityParameters.tokenY, liquidityParameters.binStep);

        if (!isPairWhitelisted(address(pairInfo.LBPair))) revert TraderJoeV2PoolNotWhitelisted();

        ITokenManager tokenManager = DeploymentConstants.getTokenManager();

        bytes32 tokenX = tokenManager.tokenAddressToSymbol(address(liquidityParameters.tokenX));
        bytes32 tokenY = tokenManager.tokenAddressToSymbol(address(liquidityParameters.tokenY));

        require(_getAvailableBalance(tokenX) >= liquidityParameters.amountX, "Insufficient balance");
        require(_getAvailableBalance(tokenY) >= liquidityParameters.amountY, "Insufficient balance");

        liquidityParameters.to = address(this);
        liquidityParameters.refundTo = address(this);

        address(liquidityParameters.tokenX).safeApprove(address(traderJoeV2Router), 0);
        address(liquidityParameters.tokenY).safeApprove(address(traderJoeV2Router), 0);

        address(liquidityParameters.tokenX).safeApprove(address(traderJoeV2Router), liquidityParameters.amountX);
        address(liquidityParameters.tokenY).safeApprove(address(traderJoeV2Router), liquidityParameters.amountY);

        (uint256 amountXAdded,uint256 amountYAdded,,,uint256[] memory depositIds, uint256[] memory liquidityMinted) = traderJoeV2Router.addLiquidity(liquidityParameters);

        for (uint256 i; i < depositIds.length; ++i) {
            bool userHadBin;

            for (int256 j; uint(j) < ownedBins.length; ++j) {
                if (address(ownedBins[uint(j)].pair) == address(pairInfo.LBPair)
                && ownedBins[uint(j)].id == depositIds[i]
                ) {
                    userHadBin = true;
                    break;
                }
            }

            if (!userHadBin) {
                ownedBins.push(TraderJoeV2Bin(pairInfo.LBPair, uint24(depositIds[i])));
            }
        }

        _syncExposure(tokenManager, address(liquidityParameters.tokenX));
        _syncExposure(tokenManager, address(liquidityParameters.tokenY));

        if (maxBinsPerPrimeAccount() > 0 && ownedBins.length > maxBinsPerPrimeAccount()) revert TooManyBins();

        emit AddLiquidityTraderJoeV2(msg.sender, address(pairInfo.LBPair), depositIds, liquidityMinted, tokenX, tokenY, amountXAdded, amountYAdded, block.timestamp);
    }

    /**
     * @dev Unwinds a TraderJoe V2 position whose underlying pair contains at least one
     *      token that is no longer registered in TokenManager (e.g. delisted).
     *      The normal removeLiquidity flow reverts for such positions because the
     *      TokenManager-dependent pricing and exposure-sync paths revert on the
     *      unsupported token. This method burns the bins directly on the LB pair
     *      (no router), credits both underlying tokens to the PrimeAccount, and
     *      only calls _syncExposure for the side(s) that are still supported,
     *      leaving the unsupported token sitting untracked in the account's balance.
     * @param pair the LBPair holding the bins to unwind
     * @param ids the bin ids to burn
     * @param amounts the LB token amounts per bin to burn
     */
    function unwindUnsupportedTraderJoeV2Position(
        ILBPair pair,
        uint256[] calldata ids,
        uint256[] calldata amounts
    ) external nonReentrant onlyOwnerOrWhitelistedLiquidator noBorrowInTheSameBlock {
        // Safety: only pairs the account already tracks in its bin storage may be
        // unwound here. Those entries can only have been added via the normal
        // fund/add flows, which enforce isPairWhitelisted at the time of entry —
        // so `pair` is guaranteed to be a real, once-whitelisted LB pair and not
        // an arbitrary attacker-supplied address.
        _requirePairTracked(pair);

        address tokenX = address(pair.getTokenX());
        address tokenY = address(pair.getTokenY());

        ITokenManager tokenManager = DeploymentConstants.getTokenManager();
        bool tokenXSupported = tokenManager.isTokenAssetActive(tokenX);
        bool tokenYSupported = tokenManager.isTokenAssetActive(tokenY);
        if (tokenXSupported && tokenYSupported) revert BothTokensSupported();

        // Burn directly on the pair; from = to = this account, so no approval is needed.
        pair.burn(address(this), address(this), ids, amounts);

        _cleanEmptyBinsFor(pair);

        // Only sync exposure for supported tokens — skipping unsupported avoids the
        // tokenAddressToSymbol revert and leaves the balance untracked on purpose.
        if (tokenXSupported) {
            _syncExposure(tokenManager, tokenX);
        }
        if (tokenYSupported) {
            _syncExposure(tokenManager, tokenY);
        }

        emit UnwoundUnsupportedTraderJoeV2Position(msg.sender, address(pair), ids, amounts, tokenX, tokenY, block.timestamp);
    }

    function _requirePairTracked(ILBPair pair) private view {
        TraderJoeV2Bin[] memory binsView = DiamondStorageLib.getTjV2OwnedBinsView();
        for (uint256 i; i < binsView.length; ++i) {
            if (address(binsView[i].pair) == address(pair)) return;
        }
        revert PairNotTrackedInOwnedBins();
    }

    function _cleanEmptyBinsFor(ILBPair pair) private {
        TraderJoeV2Bin[] storage binsStorage = getOwnedTraderJoeV2BinsStorage();
        for (int256 i; uint(i) < binsStorage.length; i++) {
            if (address(binsStorage[uint(i)].pair) == address(pair)) {
                TraderJoeV2Bin storage bin = binsStorage[uint(i)];
                if (bin.pair.balanceOf(address(this), bin.id) == 0) {
                    binsStorage[uint(i)] = binsStorage[binsStorage.length - 1];
                    i--;
                    binsStorage.pop();
                }
            }
        }
    }

    function removeLiquidityTraderJoeV2(ILBRouter traderJoeV2Router, RemoveLiquidityParameters memory parameters) external nonReentrant onlyOwnerOrLiquidation noBorrowInTheSameBlock {
        if (!isRouterWhitelisted(address(traderJoeV2Router))) revert TraderJoeV2RouterNotWhitelisted();
        ILBPair lbPair = ILBPair(traderJoeV2Router.getFactory().getLBPairInformation(parameters.tokenX, parameters.tokenY, parameters.binStep).LBPair);

        if (!isPairWhitelisted(address(lbPair))) revert TraderJoeV2PoolNotWhitelisted();

        lbPair.approveForAll(address(traderJoeV2Router), true);

        (uint256 amountXReceived, uint256 amountYReceived) = _removeLiquidity(traderJoeV2Router, parameters);

        TraderJoeV2Bin[] storage binsStorage = getOwnedTraderJoeV2BinsStorage();

        for (int256 i; uint(i) < binsStorage.length; i++) {
            if (address(binsStorage[uint(i)].pair) == address(lbPair)) {
                TraderJoeV2Bin storage bin = binsStorage[uint(i)];
                if (bin.pair.balanceOf(address(this), bin.id) == 0) {
                    binsStorage[uint(i)] = binsStorage[binsStorage.length - 1];
                    i--;
                    binsStorage.pop();
                }
            }
        }

         ITokenManager tokenManager = DeploymentConstants.getTokenManager();
        bytes32 tokenX = tokenManager.tokenAddressToSymbol(address(parameters.tokenX));
        bytes32 tokenY = tokenManager.tokenAddressToSymbol(address(parameters.tokenY));

        _syncExposure(tokenManager, address(parameters.tokenX));
        _syncExposure(tokenManager, address(parameters.tokenY));

        emit RemoveLiquidityTraderJoeV2(msg.sender, address(lbPair), parameters.ids, parameters.amounts, tokenX, tokenY, block.timestamp);
    }

    /**
     * @dev emitted after adding liquidity to TraderJoe V2
     * @param user the address of user providing liquidity
     * @param pair TraderJoe V2 pair
     * @param binIds the ids of bin
     * @param liquidityMinted amount of liquidity minted per bin
     * @param firstAsset first asset provided for liquidity
     * @param secondAsset second asset provided for liquidity
     * @param firstAmount amount of the first asset used
     * @param secondAmount amount of the second asset used
     * @param timestamp time of the transaction
     **/
    event AddLiquidityTraderJoeV2(address indexed user, address indexed pair, uint256[] binIds, uint[] liquidityMinted, bytes32 firstAsset, bytes32 secondAsset, uint firstAmount, uint secondAmount, uint256 timestamp);

    /**
     * @dev emitted after removing liquidity from TraderJoe V2
     * @param user the address of user removing liquidity
     * @param pair TraderJoe V2 pair
     * @param binIds the ids of bin
     * @param amounts The list of amounts to burn of each id in binIds
     * @param firstAsset first asset provided for liquidity
     * @param secondAsset second asset provided for liquidity
     * @param timestamp time of the transaction
     **/
    event RemoveLiquidityTraderJoeV2(address indexed user, address indexed pair, uint256[] binIds, uint[] amounts, bytes32 firstAsset, bytes32 secondAsset, uint256 timestamp);

    /**
     * @dev emitted after funding account with TraderJoe V2 LB tokens
     * @param user the address of user removing liquidity
     * @param pair TraderJoe V2 pair
     * @param binIds the ids of bin
     * @param amounts The list of amounts to burn of each id in binIds
     * @param timestamp time of the transaction
     **/
    event FundedLiquidityTraderJoeV2(address indexed user, address indexed pair, uint256[] binIds, uint[] amounts, uint256 timestamp);

    /**
     * @dev emitted after withdrawing TraderJoe V2 LB tokens
     * @param user the address of user removing liquidity
     * @param pair TraderJoe V2 pair
     * @param binIds the ids of bin
     * @param amounts The list of amounts to burn of each id in binIds
     * @param timestamp time of the transaction
     **/
    event WithdrawnLiquidityTraderJoeV2(address indexed user, address indexed pair, uint256[] binIds, uint[] amounts, uint256 timestamp);

    /**
     * @dev emitted when an unsupported TraderJoe V2 position is unwound via unwindUnsupportedTraderJoeV2Position
     * @param user the caller (owner or whitelisted liquidator)
     * @param pair TraderJoe V2 pair that was unwound
     * @param binIds the bin ids burned
     * @param amounts the LB token amounts burned per bin
     * @param tokenX the pair's token X address
     * @param tokenY the pair's token Y address
     * @param timestamp time of the transaction
     **/
    event UnwoundUnsupportedTraderJoeV2Position(address indexed user, address indexed pair, uint256[] binIds, uint[] amounts, address tokenX, address tokenY, uint256 timestamp);

    error TraderJoeV2PoolNotWhitelisted();

    error TraderJoeV2RouterNotWhitelisted();

    error TooManyBins();

    error TraderJoeV2NoRewardHook();

    error IdOutOfRange();

    error PairNotTrackedInOwnedBins();

    error BothTokensSupported();
}

contracts/facets/WithdrawalIntentFacet.s.content:
// SPDX-License-Identifier: BUSL-1.1
// Last deployed from commit:
pragma solidity 0.8.17;

import "../ReentrancyGuardKeccak.sol";
import "../interfaces/facets/IWithdrawalIntentFacet.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import "@uniswap/lib/contracts/libraries/TransferHelper.sol";
import {DiamondStorageLib} from "../lib/DiamondStorageLib.sol";
import {LeverageTierLib} from "../lib/LeverageTierLib.sol";
import "../lib/GmxV2FeesHelper.sol";
import {GlvHelper} from "../lib/GlvHelper.sol";
import {IGmxReader} from "../interfaces/gmx-v2/IGmxReader.sol";
import {IGlvReader} from "../interfaces/gmx-v2/IGlvReader.sol";
import {ISmartLoanLiquidationFacet} from "../interfaces/facets/ISmartLoanLiquidationFacet.sol";


contract WithdrawalIntentFacet is IWithdrawalIntentFacet, ReentrancyGuardKeccak, GmxV2FeesHelper, GlvHelper {
    using TransferHelper for address;

    // for prime token burning
    address private constant BURN_ADDRESS = 0x000000000000000000000000000000000000dEaD;

    function createWithdrawalIntent(bytes32 _asset, uint256 _amount) external onlyOwner nonReentrant notInLiquidation {
        require(_amount > 0, "Amount must be greater than zero");

        IERC20Metadata token = getERC20TokenInstance(_asset, true);
        address tokenAddress = address(token);

        _removeExpiredIntents(tokenAddress);

        uint256 availableBalance = getAvailableBalance(_asset);
        if(_amount > availableBalance) {
            revert InsufficientAvailableBalance(_amount, availableBalance);
        }

        DiamondStorageLib.WithdrawalIntentsStorage storage wis = DiamondStorageLib.withdrawalIntentsStorage();
        uint256 actionableAt = block.timestamp + 24 hours;
        uint256 expiresAt = actionableAt + 48 hours;

        wis.intents[tokenAddress].push(DiamondStorageLib.WithdrawalIntent({
            amount: _amount,
            actionableAt: actionableAt,
            expiresAt: expiresAt
        }));

        emit WithdrawalIntentCreated(_asset, _amount, actionableAt, expiresAt);
    }

    function executeWithdrawalIntent(bytes32 _asset, uint256[] calldata intentIndices) external onlyOwner noBorrowInTheSameBlock nonReentrant canRepayDebtFully remainsSolvent notInLiquidation {
        IERC20Metadata token = getERC20TokenInstance(_asset, true);
        address tokenAddress = address(token);
        ITokenManager tokenManager = DeploymentConstants.getTokenManager();
        GmxTokenPrices memory gmTokenPrices;
        uint256 finalAmount = validateWithdrawalIntents(tokenAddress, intentIndices);
        uint256 feesCollected = 0;

        if (tokenManager.isGmxMarketWhitelisted(tokenAddress) || tokenManager.isGlvTokenWhitelisted(tokenAddress)) {
            if(tokenManager.isGlvTokenWhitelisted(tokenAddress)) {
                UnifiedGmxTokenPricesAndAddresses memory pricesAndAddresses = _getUnifiedGlvTokenPricesAndAddresses(address(token));
                gmTokenPrices = GmxTokenPrices({
                gmTokenPrice: pricesAndAddresses.gmTokenPrice,
                longTokenPrice: pricesAndAddresses.longTokenPrice,
                shortTokenPrice: pricesAndAddresses.shortTokenPrice
                });
            } else  { // isGmxMarketWhitelisted
                gmTokenPrices = _getGmxTokenPrices(tokenAddress);    
            }
            feesCollected = _sweepFees(tokenAddress, gmTokenPrices);
            feesCollected = feesCollected > finalAmount ? finalAmount : feesCollected; // Ensure we don't deduct more than the final amount
            if (feesCollected > 0) {
                finalAmount -= feesCollected;
                emit FeesSweptDuringWithdrawalIntent(
                    tokenAddress,
                    feesCollected,
                    _asset,
                    finalAmount + feesCollected,
                    block.timestamp
                );
            }
        }

        require(finalAmount > 0, "No valid amount to withdraw");

        uint256 totalDebt = _getDebt();
        LeverageTierLib.updatePrimeDebtSnapshot(totalDebt);

        uint256 currentPrimeDebt = LeverageTierLib.getCurrentPrimeDebt(totalDebt);
        if(currentPrimeDebt > 0.05 * 1e18){
            _repayPrimeDebtToExecuteWithdrawalIntent(currentPrimeDebt, totalDebt, tokenManager);

        }

        DiamondStorageLib.WithdrawalIntentsStorage storage wis = DiamondStorageLib.withdrawalIntentsStorage();
        DiamondStorageLib.WithdrawalIntent[] storage intents = wis.intents[tokenAddress];

        // Remove intents from highest to lowest index
        for(uint256 i = intentIndices.length; i > 0; i--) {
            uint256 indexToRemove = intentIndices[i - 1];

            uint256 lastIndex = intents.length - 1;
            if (indexToRemove != lastIndex) {
                intents[indexToRemove] = intents[lastIndex];
            }
            intents.pop();
        }

        address(token).safeTransfer(msg.sender, finalAmount);

        if (tokenManager.isGmxMarketWhitelisted(tokenAddress)) {
            // OPTIMIZED: Use inherited method from GmxV2FeesHelper
            _updateBenchmark(tokenAddress, gmTokenPrices.gmTokenPrice, gmTokenPrices.longTokenPrice, gmTokenPrices.shortTokenPrice);

            emit BenchmarkUpdatedDuringWithdrawalIntent(
                tokenAddress,
                gmTokenPrices.gmTokenPrice,
                gmTokenPrices.longTokenPrice,
                gmTokenPrices.shortTokenPrice,
                block.timestamp
            );
        }

        // Update exposure only if not PRIME token
        if(_asset == bytes32("PRIME")) {
            tokenManager.updateUserExposure(address(this), tokenAddress);
        } else {
            _syncExposure(tokenManager, tokenAddress);
        }

        emit WithdrawalIntentExecuted(_asset, finalAmount, block.timestamp);
        emit WithdrawalIntentsProcessed(
            _asset,
            intentIndices.length,
            finalAmount,
            feesCollected,
            block.timestamp
        );
    }

    function _repayPrimeDebtToExecuteWithdrawalIntent(uint256 amount, uint256 totalDebt, ITokenManager tokenManager) internal {
        require(_getAvailableBalance("PRIME") >= amount, "Not enough PRIME to repay the debt");
        address primeTokenAddress = tokenManager.getAssetAddress("PRIME", true);

        // Split: 50% burn, 50% to treasury
        uint256 burnAmount = amount / 2;
        uint256 treasuryAmount = amount - burnAmount;


        primeTokenAddress.safeTransfer(BURN_ADDRESS, burnAmount);

        address treasuryAddress = DeploymentConstants.getTreasuryAddress();
        primeTokenAddress.safeTransfer(treasuryAddress, treasuryAmount);

        // Update debt (need to update the recorded debt, not just subtract from current)
        uint256 recordedDebt = DiamondStorageLib.getPrimeDebt();
        DiamondStorageLib.setPrimeDebt(recordedDebt > amount ? recordedDebt - amount : 0);

        uint256 currentDebtAfter = LeverageTierLib.getCurrentPrimeDebt(totalDebt);

        emit PrimeDebtRepaid(msg.sender, amount, currentDebtAfter, block.timestamp);
    }




    function cancelWithdrawalIntent(bytes32 _asset, uint256 intentIndex) external onlyWhitelistedLiquidatorsAndInsolvencySnapshotOrOwner nonReentrant {
        address tokenAddress = address(getERC20TokenInstance(_asset, true));
        DiamondStorageLib.WithdrawalIntentsStorage storage wis = DiamondStorageLib.withdrawalIntentsStorage();
        DiamondStorageLib.WithdrawalIntent[] storage intents = wis.intents[tokenAddress];

        require(intentIndex < intents.length, "Invalid intent index");

        uint256 amount = intents[intentIndex].amount;
        uint256 actionableAt = intents[intentIndex].actionableAt;
        uint256 expiresAt = intents[intentIndex].expiresAt;

        uint256 lastIndex = intents.length - 1;
        if (intentIndex != lastIndex) {
            intents[intentIndex] = intents[lastIndex];
        }
        intents.pop();

        emit WithdrawalIntentCanceled(_asset, amount, block.timestamp);
        emit WithdrawalIntentCanceledDetailed(
            _asset,
            intentIndex,
            amount,
            actionableAt,
            expiresAt,
            block.timestamp
        );
    }

    function clearExpiredIntents(bytes32 _asset) external {
        address tokenAddress = address(getERC20TokenInstance(_asset, true));
        uint256 clearedCount = _removeExpiredIntents(tokenAddress);

        if (clearedCount > 0) {
            emit ExpiredIntentsCleared(_asset, clearedCount, block.timestamp);
        }
    }

    function _removeExpiredIntents(address tokenAddress) internal returns (uint256 clearedCount) {
        DiamondStorageLib.WithdrawalIntentsStorage storage wis = DiamondStorageLib.withdrawalIntentsStorage();
        DiamondStorageLib.WithdrawalIntent[] storage intents = wis.intents[tokenAddress];

        uint256 i = 0;
        clearedCount = 0;
        while (i < intents.length) {
            if (block.timestamp > intents[i].expiresAt) {
                uint256 lastIndex = intents.length - 1;
                if (i != lastIndex) {
                    intents[i] = intents[lastIndex];
                }
                intents.pop();
                clearedCount++;
            } else {
                i++;
            }
        }
    }

    function validateWithdrawalIntents(
        address tokenAddress,
        uint256[] calldata intentIndices
    ) internal view returns (uint256 finalAmount) {
        require(intentIndices.length > 0, "Must provide at least one intent");

        DiamondStorageLib.WithdrawalIntentsStorage storage wis = DiamondStorageLib.withdrawalIntentsStorage();
        DiamondStorageLib.WithdrawalIntent[] storage intents = wis.intents[tokenAddress];

        uint256 totalAmount = 0;

        for(uint256 i = 0; i < intentIndices.length; i++) {
            require(
                i == 0 || intentIndices[i] > intentIndices[i-1],
                "Intent indices must be strictly increasing"
            );

            uint256 index = intentIndices[i];
            require(index < intents.length, "Invalid intent index");

            DiamondStorageLib.WithdrawalIntent storage intent = intents[index];
            require(block.timestamp >= intent.actionableAt, "Intent not matured");
            require(block.timestamp <= intent.expiresAt, "Intent expired");

            totalAmount += intent.amount;
        }

        return totalAmount;
    }

    function getUserIntents(bytes32 _asset) external view returns (IntentInfo[] memory) {
        address tokenAddress = address(getERC20TokenInstance(_asset, true));
        DiamondStorageLib.WithdrawalIntentsStorage storage wis = DiamondStorageLib.withdrawalIntentsStorage();
        DiamondStorageLib.WithdrawalIntent[] storage intents = wis.intents[tokenAddress];

        IntentInfo[] memory intentInfos = new IntentInfo[](intents.length);

        for (uint256 i = 0; i < intents.length; i++) {
            DiamondStorageLib.WithdrawalIntent storage intent = intents[i];
            intentInfos[i] = IntentInfo({
                amount: intent.amount,
                actionableAt: intent.actionableAt,
                expiresAt: intent.expiresAt,
                isPending: block.timestamp < intent.actionableAt,
                isActionable: block.timestamp >= intent.actionableAt && block.timestamp <= intent.expiresAt,
                isExpired: block.timestamp > intent.expiresAt
            });
        }

        return intentInfos;
    }

    function getTotalIntentAmount(bytes32 _asset) public view returns (uint256) {
        address tokenAddress = address(getERC20TokenInstance(_asset, true));
        DiamondStorageLib.WithdrawalIntentsStorage storage wis = DiamondStorageLib.withdrawalIntentsStorage();
        DiamondStorageLib.WithdrawalIntent[] storage intents = wis.intents[tokenAddress];

        uint256 totalPending = 0;
        for (uint256 i = 0; i < intents.length; i++) {
            // Only count non-expired intents
            if (block.timestamp <= intents[i].expiresAt) {
                totalPending += intents[i].amount;
            }
        }

        return totalPending;
    }

    function getAvailableBalance(bytes32 _asset) public view returns (uint256) {
        IERC20Metadata token = getERC20TokenInstance(_asset, true);
        uint256 balance = token.balanceOf(address(this));
        uint256 stakedAmount = DiamondStorageLib.getStakedTokenAmount(address(token));
        balance = balance > stakedAmount ? balance - stakedAmount: 0;
        uint256 pendingWithdrawals = getTotalIntentAmount(_asset);
        return balance > pendingWithdrawals ? balance - pendingWithdrawals : 0;
    }

    function getAvailableBalancePayable(bytes32 _asset) external payable returns (uint256) {
        return getAvailableBalance(_asset);
    }

    /**
     * @dev Allows whitelisted liquidators to cancel a PA's withdrawal intents once an
     * insolvency snapshot is in place, so intents whose underlying token amounts are no
     * longer available cannot remain as stale obligations blocking liquidation accounting.
     * Owners retain unrestricted cancel rights.
     */
    modifier onlyWhitelistedLiquidatorsAndInsolvencySnapshotOrOwner() {
        bool isWhitelistedLiquidator = ISmartLoanLiquidationFacet(DeploymentConstants.getDiamondAddress()).isLiquidatorWhitelisted(msg.sender);
        if (isWhitelistedLiquidator) {
            DiamondStorageLib.LiquidationSnapshotStorage storage ls = DiamondStorageLib.liquidationSnapshotStorage();
            require(ls.lastInsolventTimestamp > 0, "No insolvency snapshot - call snapshotInsolvency first");
        } else {
            DiamondStorageLib.enforceIsContractOwner();
        }
        _;
    }

    error InsufficientAvailableBalance(uint256 amount, uint256 availableBalance);
    /* ========== ERRORS ========== */
    error NeitherGmxOrGlv();

    // NEW EVENTS FOR ENHANCED MONITORING
    event FeesSweptDuringWithdrawalIntent(
        address indexed gmToken,
        uint256 feesCollected,
        bytes32 indexed asset,
        uint256 originalAmount,
        uint256 timestamp
    );

    event BenchmarkUpdatedDuringWithdrawalIntent(
        address indexed gmToken,
        uint256 gmTokenPrice,
        uint256 longTokenPrice,
        uint256 shortTokenPrice,
        uint256 timestamp
    );

    event WithdrawalIntentsProcessed(
        bytes32 indexed asset,
        uint256 intentsProcessed,
        uint256 finalAmount,
        uint256 feesDeducted,
        uint256 timestamp
    );

    event WithdrawalIntentCanceledDetailed(
        bytes32 indexed asset,
        uint256 intentIndex,
        uint256 amount,
        uint256 actionableAt,
        uint256 expiresAt,
        uint256 timestamp
    );

    event ExpiredIntentsCleared(
        bytes32 indexed asset,
        uint256 clearedCount,
        uint256 timestamp
    );

    event PrimeDebtRepaid(
        address indexed user, 
        uint256 amount, 
        uint256 remainingDebt, 
        uint256 timestamp
    );
}

contracts/facets/WithdrawUnsupportedPosi.content:
// SPDX-License-Identifier: BUSL-1.1
// Last deployed from commit: cc89474c960bad83ebf009a447365d5b50e193ae;
pragma solidity 0.8.17;

import "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

import {DiamondStorageLib} from "../lib/DiamondStorageLib.sol";
import {LeverageTierLib} from "../lib/LeverageTierLib.sol";
import "../interfaces/ITokenManager.sol";
import "../ReentrancyGuardKeccak.sol";
import "../lib/DiamondMethodsAccess.sol";
import "../lib/arbitrum/DeploymentConstants.sol";
import "../interfaces/IWithdrawUnsupportedPositionsFacet.sol";
import "../PrimeAccountModifiers.sol";

contract WithdrawUnsupportedPositionsFacet is
    ReentrancyGuardKeccak,
    DiamondMethodsAccess,
    IWithdrawUnsupportedPositionsFacet,
    PrimeAccountModifiers
{
    using SafeERC20 for IERC20Metadata;

    /// @notice Checks if the contract holds any unsupported assets
    /// @dev Used by UI to determine whether to display withdrawable options
    /// @return True if any unsupported assets exist, false otherwise
    function hasUnsupportedAssets() external view returns (bool) {
        ITokenManager tokenManager = DeploymentConstants.getTokenManager();
        address[] memory unsupportedAssets = tokenManager.getUnsupportedWithdrawableAssets();

        for (uint256 i = 0; i < unsupportedAssets.length; i++) {
            if (IERC20Metadata(unsupportedAssets[i]).balanceOf(address(this)) > 0) {
                return true;
            }
        }

        return false;
    }

    /// @notice Withdraws all unsupported asset positions from the contract
    /// @dev Gets asset list dynamically from TokenManager - no more hardcoded addresses
    function withdrawUnsupportedPositions() external nonReentrant onlyOwner remainsSolvent {
        ITokenManager tokenManager = DeploymentConstants.getTokenManager();
        address[] memory unsupportedAssets = tokenManager.getUnsupportedWithdrawableAssets();
        uint256 totalWithdrawn = 0;

        for (uint256 i = 0; i < unsupportedAssets.length; i++) {
            _verifyAssetUnsupported(tokenManager, unsupportedAssets[i]);
            if (_withdrawAsset(unsupportedAssets[i])) {
                totalWithdrawn++;
            }
        }

        emit WithdrawalCompleted(msg.sender, totalWithdrawn, block.timestamp);
    }

    /// @notice Withdraws a single asset from the contract to the owner
    /// @param assetAddress The address of the asset to withdraw
    /// @return success True if withdrawal occurred (balance > 0), false otherwise
    function _withdrawAsset(address assetAddress) private returns (bool success) {
        IERC20Metadata token = IERC20Metadata(assetAddress);
        uint256 balance = token.balanceOf(address(this));

        if (balance > 0) {
            uint256 ownerInitialBalance = token.balanceOf(msg.sender);
            token.safeTransfer(msg.sender, balance);

            // Verify transfer completed correctly
            uint256 expectedOwnerBalance = ownerInitialBalance + balance;
            uint256 actualOwnerBalance = token.balanceOf(msg.sender);
            if (actualOwnerBalance != expectedOwnerBalance) {
                revert InvalidOwnerBalanceAfterTransfer(expectedOwnerBalance, actualOwnerBalance);
            }

            uint256 contractBalance = token.balanceOf(address(this));
            if (contractBalance != 0) {
                revert InvalidContractBalanceAfterTransfer(contractBalance);
            }

            emit UnsupportedAssetWithdrawn(
                msg.sender,
                assetAddress,
                balance,
                block.timestamp
            );

            return true;
        }

        return false;
    }

    /// @notice Verifies that an asset is truly unsupported in TokenManager
    /// @param tokenManager The TokenManager contract instance
    /// @param assetAddress The address of the asset to verify
    function _verifyAssetUnsupported(ITokenManager tokenManager, address assetAddress) private view {
        // Asset must NOT be PRIME
        address primeAddress = tokenManager.getAssetAddress('PRIME', true);
        if (assetAddress == primeAddress) {
            revert CannotWithdrawPrimeToken(assetAddress);
        }

        // Asset must NOT be active
        if (tokenManager.isTokenAssetActive(assetAddress)) {
            revert AssetStillActive(assetAddress);
        }

        // Asset must have no symbol mapping
        bytes32 symbol = tokenManager.tokenAddressToSymbol(assetAddress);
        if (symbol != bytes32(0)) {
            revert AssetHasSymbolMapping(assetAddress, symbol);
        }

        // Asset must have zero debt coverage
        uint256 debtCov = tokenManager.debtCoverage(assetAddress);
        if (debtCov != 0) {
            revert AssetHasDebtCoverage(assetAddress, debtCov);
        }

        // Asset must have zero tiered debt coverage for BASIC tier
        uint256 basicTierCov = tokenManager.tieredDebtCoverage(LeverageTierLib.LeverageTier.BASIC, assetAddress);
        if (basicTierCov != 0) {
            revert AssetHasBasicTierDebtCoverage(assetAddress, basicTierCov);
        }

        // Asset must have zero tiered debt coverage for PREMIUM tier
        uint256 premiumTierCov = tokenManager.tieredDebtCoverage(LeverageTierLib.LeverageTier.PREMIUM, assetAddress);
        if (premiumTierCov != 0) {
            revert AssetHasPremiumTierDebtCoverage(assetAddress, premiumTierCov);
        }
    }
}

